// ColorHub films: how directors use color. Built by tools/passages.py --films; method and sources in research/PASSAGES-FILMS.md.
// Films under copyright: original text only, no stills, no frame-sampled palettes; `colors` are named colors we chose to
// illustrate the text ("colors discussed"). Early films (`early`, before 1930) are public domain in the US: `img` is a small
// Wikimedia Commons copy in img/films/ and `palette` is sampled from that scan. Hex values are screen approximations.
window.FILMS = [
{"id": "the-wizard-of-oz", "title": "The Wizard of Oz", "year": 1939, "director": "Victor Fleming", "country": "United States", "dek": "A film that saves its color for a door. Kansas is sepia; Oz arrives in full three-strip Technicolor.", "body": ["The Wizard of Oz is built on one withheld reveal. The Kansas scenes were shot in black and white and toned sepia, so the opening feels like an old photograph. Every scene in Oz was shot in three-strip Technicolor, which needed large, hot studio lights. The contrast between the two is the whole idea: the audience waits for color the way Dorothy waits for somewhere over the rainbow.", "The switch happens in a single move. For the reshoots, the inside of the farmhouse was painted sepia. When the door opens, the figure in the doorway is Garland's stand-in, Bobbie Koshay, in a sepia-colored gingham dress. She steps back out of frame, the camera moves through, and the bright world outside reads as a shock.", "Once in Oz, the film uses a few saturated colors as signposts. The art department reportedly took almost a week to settle the exact [[Yellow]] of the brick road. In L. Frank Baum's book, Dorothy's shoes are silver. Screenwriter Noel Langley is credited with changing them to red to make the most of Technicolor. Even then the shade needed care: bright red sequins could photograph orange, so darker ones were used. Then comes the [[Emerald]] City, and the horses in it were tinted with Jell-O powder.", "The lesson for a designer is pacing. A palette feels richer when the viewer has been kept without it first."], "images": [{"src": "img/films/the-wizard-of-oz-r1.jpg", "w": 650, "h": 861, "alt": "Line drawing of Dorothy in a white dress and silver shoes, arms raised, against a pale blue circle.", "caption": "W. W. Denslow's Dorothy for L. Frank Baum's book. In the book her shoes are silver; the film made them red. A book illustration, not from the film.", "credit": "W. W. Denslow · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Dorothy_Gale_with_silver_shoes.jpg"}, {"src": "img/films/the-wizard-of-oz-r2.jpg", "w": 534, "h": 332, "alt": "Green-tinted drawing of Toto sitting before the domes and towers of the Emerald City.", "caption": "Toto at the Emerald City, W. W. Denslow's illustration from the 1900 first edition of Baum's book. A book illustration, not from the film.", "credit": "W. W. Denslow · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Emerald_City.jpg"}], "colors": [{"name": "Sepia", "h": "#8A6A4F", "app": "Sepia", "note": "The toned black and white of Kansas, at the start and the end"}, {"name": "Ruby red", "h": "#9B111E", "app": "Carmine", "note": "Dorothy's slippers; silver in the book, made red for Technicolor"}, {"name": "Yellow", "h": "#F2C81F", "app": "Yellow", "note": "The brick road, a shade the art department debated for days"}, {"name": "Emerald", "h": "#50C878", "app": "Emerald", "note": "The Emerald City, the goal the whole road points toward"}], "facts": [{"label": "Cinematography", "value": "Harold Rosson"}, {"label": "Process", "value": "Three-strip Technicolor (Oz); sepia-toned black and white (Kansas)"}, {"label": "Studio", "value": "Metro-Goldwyn-Mayer"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Wizard_of_Oz_(1939_film)"}, {"label": "Warner Bros.", "url": "https://www.warnerbros.com/movies/wizard-oz"}], "sources": ["https://en.wikipedia.org/wiki/The_Wizard_of_Oz_(1939_film)", "https://en.wikipedia.org/wiki/Ruby_slippers", "https://www.warnerbros.com/movies/wizard-oz"]},
{"id": "black-narcissus", "title": "Black Narcissus", "year": 1947, "director": "Michael Powell and Emeric Pressburger", "country": "United Kingdom", "dek": "A Himalayan convent built entirely in a London studio, where color tracks a nun's unravelling.", "body": ["Black Narcissus takes place in a convent high in the Himalayas, but no frame was shot there. The film was made at Pinewood Studios near London, with a few days at a Sussex garden full of Asian plants. Alfred Junge's sets, large painted landscapes and matte paintings supplied the mountains. Working in a studio gave cinematographer Jack Cardiff full control of the light, and he used it.", "Cardiff said he was a great admirer of Vermeer and Caravaggio, and that he copied their habit of keeping the lighting simple. You can see it in the cool window light on the nuns' white habits. He also pushed color away from realism with fog, filters and diffusion, so the palette reads as feeling rather than record.", "The clearest device is red. Sister Ruth, played by Kathleen Byron, gives up her vows in stages, and color marks each step. She trades her habit for a red dress. She paints on [[Crimson|red lipstick]] in front of Sister Clodagh, an act of open defiance. When she faints, the screen does not fade to black but floods with red, a choice critics often read as a view of her mind breaking. Late in the film, as she stalks Clodagh, the light turns to pinks, mauves and greys.", "The takeaway is restraint. White and cool tones hold for most of the film, so when red finally takes over, it lands. Cardiff won the Academy Award for color cinematography, and Junge won for art direction."], "images": [{"src": "img/films/black-narcissus-r1.jpg", "w": 803, "h": 900, "alt": "Vermeer's painting of a maid pouring milk beside a window, lit by cool daylight.", "caption": "Vermeer's The Milkmaid (about 1658). Jack Cardiff named Vermeer as a model for simple light, like this single window. A painting, not from the film.", "credit": "Johannes Vermeer · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Johannes_Vermeer_-_Het_melkmeisje_-_Google_Art_Project.jpg"}, {"src": "img/films/black-narcissus-r2.jpg", "w": 900, "h": 842, "alt": "Caravaggio's dark painting of men at a table, crossed by one diagonal beam of light.", "caption": "Caravaggio's The Calling of Saint Matthew (1599-1600), the other painter Cardiff named: one hard beam of light in a dark room. A painting, not from the film.", "credit": "Caravaggio · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Caravaggio,_Michelangelo_Merisi_da_-_The_Calling_of_Saint_Matthew_-_1599-1600_(hi_res).jpg"}, {"src": "img/films/black-narcissus-r3.jpg", "w": 900, "h": 600, "alt": "A mass of bright pink-purple rhododendron flowers on a shrub.", "caption": "Rhododendrons at Leonardslee Gardens in Sussex, the garden of Asian plants where the film shot for a few days. A photo of the real garden (2022), not a still.", "credit": "Michael Garlick · CC BY-SA 2.0", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Leonardslee_Gardens,_Rhododendron_-_geograph.org.uk_-_7159061.jpg"}], "colors": [{"name": "Habit white", "h": "#F2F0EA", "app": "White", "note": "The nuns' habits, lit with cool, simple window light"}, {"name": "Lipstick red", "h": "#C8102E", "app": "Crimson", "note": "Sister Ruth's lipstick and dress, the mark of her break with the order"}, {"name": "Scarlet", "h": "#FF2400", "app": "Scarlet", "note": "The fade to red when Ruth faints"}, {"name": "Mauve", "h": "#A8778F", "app": "Mauve", "note": "The pink and mauve light of the final stalking scenes"}], "facts": [{"label": "Cinematography", "value": "Jack Cardiff (Academy Award, color cinematography)"}, {"label": "Production design", "value": "Alfred Junge (Academy Award, art direction)"}, {"label": "Process", "value": "Technicolor"}, {"label": "Filmed at", "value": "Pinewood Studios and Leonardslee Gardens, Sussex"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Black_Narcissus_(1947_film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/632-black-narcissus"}], "sources": ["https://en.wikipedia.org/wiki/Black_Narcissus_(1947_film)", "https://www.criterion.com/films/632-black-narcissus", "https://colourandfilm.com/2021/01/04/the-exaggerated-colours-of-black-narcissus-1947-and-2020-by-sarah-street/", "https://www.baltimoresun.com/bs-mtblog-2010-07-glorious_technicolor-story.html"]},
{"id": "the-red-shoes", "title": "The Red Shoes", "year": 1948, "director": "Michael Powell and Emeric Pressburger", "country": "United Kingdom", "dek": "A ballet film designed by a painter, where one pair of red shoes carries the whole story.", "body": ["The Red Shoes follows a young dancer, Victoria Page, torn between a demanding impresario and a composer. Inside it sits a ballet based on Hans Christian Andersen's tale of enchanted red shoes that make their wearer dance until she dies. The film's color work is about keeping that single red object in charge.", "The design came from Hein Heckroth, a German painter who had worked in surrealism and stage design for ballet and opera. For the 17-minute ballet, his design drawings were the plan for everything. More than a hundred drawings were turned into a guide film, which composer Brian Easdale used to time the score, and the drawings were replaced by real footage as the shoot went on. The sequence moves out of a realistic stage into painted dream spaces, which Heckroth described as showing what the dancer feels as well as what the audience sees.", "Jack Cardiff shot the film in three-strip Technicolor. Moira Shearer's red hair echoes the [[Scarlet|scarlet]] shoes, so the color lives on her body before it reaches her feet. Critics often point to how the film pairs red with white across her face and costumes, and many read that pairing as passion against calm, or art against ordinary life. Off stage, the theatrical color carries on into offices and dressing rooms, often through flowers.", "Three-strip film recorded each color on a separate negative. Over decades those negatives shrank and grew mold, so the three images no longer lined up, leaving colored fringes. A UCLA restoration from 2006 to 2009 scanned about 600,000 frames in 4K to bring them back into register. Heckroth won the Academy Award for art direction, with Arthur Lawson."], "images": [{"src": "img/films/the-red-shoes-r1.jpg", "w": 675, "h": 900, "alt": "Watercolor of a pale girl in a flowing dress dancing wildly, her feet in red shoes.", "caption": "Anne Anderson's 1924 illustration of Hans Christian Andersen's The Red Shoes, the tale the film's ballet is built on. A book illustration, not from the film.", "credit": "Anne Anderson · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:The_Red_Shoes_-_Anne_Anderson_cropped.jpg"}], "colors": [{"name": "Scarlet", "h": "#FF2400", "app": "Scarlet", "note": "The enchanted ballet shoes, the one color the story keeps returning to"}, {"name": "Copper red", "h": "#B4442A", "app": "Rust", "note": "Moira Shearer's hair, echoing the shoes on her body"}, {"name": "White", "h": "#F7F6F2", "app": "White", "note": "Pale costumes and skin, the calm half of the red and white pairing"}], "facts": [{"label": "Cinematography", "value": "Jack Cardiff"}, {"label": "Production design", "value": "Hein Heckroth (Academy Award, with Arthur Lawson)"}, {"label": "Process", "value": "Three-strip Technicolor"}, {"label": "Restoration", "value": "UCLA Film & Television Archive, 2006 to 2009"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Red_Shoes_(1948_film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/233-the-red-shoes"}], "sources": ["https://en.wikipedia.org/wiki/The_Red_Shoes_(1948_film)", "https://www.criterion.com/films/233-the-red-shoes", "https://www.highdefwatch.com/post/a-masterpiece-restored-the-red-shoes-the-criterion-collection", "https://www.scenebygreen.com/2021/10/01/the-red-shoes-1948/"]},
{"id": "vertigo", "title": "Vertigo", "year": 1958, "director": "Alfred Hitchcock", "country": "United States", "dek": "Green follows one woman through two identities, and red sits behind her the first time we see her.", "body": ["In Vertigo, a detective named Scottie is hired to follow Madeleine, then later tries to remake another woman, Judy, in her image. Hitchcock gives the story a color thread you can track: green.", "We first see Madeleine at Ernie's, a real San Francisco restaurant that Hitchcock rebuilt on a Paramount soundstage. She wears a black gown under a green wrap, set against plush red walls. Red and green sit opposite each other on the color wheel, so the pairing makes her vibrate in the frame. She drives a green car. When Scottie later meets Judy on the street, she is in green too, a hint before the plot explains anything.", "The thread peaks in Judy's room at the Empire Hotel, where a green neon sign shines through the window. When she steps out fully made over as Madeleine, she walks into that green light, and the image goes soft and hazy. Critics often read green in the film as the color of the dead and of illusion. That reading is an interpretation, but the repetition is plainly deliberate.", "Costume did quiet work as well. Edith Head and Hitchcock chose a [[Grey|grey]] suit for Madeleine because grey is not a color usually given to blondes, so it would feel slightly off. A white coat, by contrast, was meant to feel natural on her. Robert Burks shot the film in VistaVision. By the 1990s the negatives had faded, and the 1996 restoration by Robert A. Harris and James C. Katz used car paint samples as a reference to bring back the [[Emerald|greens]]."], "images": [{"src": "img/films/vertigo-r1.jpg", "w": 900, "h": 675, "alt": "A black Mitchell film camera with a large round magazine, shown on a display stand.", "caption": "A Mitchell VistaVision camera from about 1953-54. VistaVision ran 35mm film sideways for a bigger frame, the format Vertigo was shot in. A photo of the equipment, not a still.", "credit": "Doug Kline · CC BY 2.0", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Debbie_Reynolds_Auction_-_Mitchell_VistaVision_Model_V-V_35mm_motion_picture_camera_circa_1953-54.jpg"}], "colors": [{"name": "Vertigo green", "h": "#3FA86B", "app": "Emerald", "note": "Madeleine's wrap and car, Judy's dress, the hotel neon"}, {"name": "Restaurant red", "h": "#8E1B1B", "app": "Carmine", "note": "The red walls of Ernie's behind Madeleine's first appearance"}, {"name": "Grey", "h": "#8C9096", "app": "Grey", "note": "Madeleine's suit, chosen because it is an unusual color for a blonde"}, {"name": "Neon green", "h": "#5CE08A", "app": "Malachite", "note": "The Empire Hotel sign that bathes Judy's transformation"}], "facts": [{"label": "Cinematography", "value": "Robert Burks"}, {"label": "Process", "value": "VistaVision, prints by Technicolor"}, {"label": "Costumes", "value": "Edith Head"}, {"label": "Restoration", "value": "Robert A. Harris and James C. Katz, 1996"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Vertigo_(film)"}, {"label": "BFI", "url": "https://www.bfi.org.uk/film/489eada8-7d7e-594c-acac-5903f43f4b85/vertigo"}], "sources": ["https://en.wikipedia.org/wiki/Vertigo_(film)", "https://reelsf.com/reelsf/vertigo-ernies-restaurant", "https://www.bfi.org.uk/film/489eada8-7d7e-594c-acac-5903f43f4b85/vertigo"]},
{"id": "contempt", "title": "Contempt (Le Mépris)", "year": 1963, "director": "Jean-Luc Godard", "country": "France / Italy", "dek": "Godard builds a collapsing marriage out of three colors: red, yellow and blue.", "body": ["Contempt is about a screenwriter, Paul, hired to rewrite a film of the Odyssey, and his wife Camille, played by Brigitte Bardot, who slowly stops loving him. Godard shot it in CinemaScope and Technicolor with Raoul Coutard, and he reduced its palette almost to a child's paint box: the primary colors.", "The clearest example opens the film. The American producers wanted more of Bardot, so Godard added a bedroom scene after he thought the film was finished. He shot her body first through a red filter, then in natural light, then through a blue filter. Critics often note that the effect cools the scene down rather than heating it up. The color is so obviously applied that you stay aware you are watching a film.", "From there the three colors keep returning. The producer drives a bright red Alfa Romeo. On Capri, Camille wears a yellow robe on the roof of Casa Malaparte, a red masonry house above the sea. Painted statues of Homer's gods stare out between scenes. One critic reads red as desire and blue as its absence, and the film ends on the [[Azure|blue]] Mediterranean. Treat that as one reading among several, but the pairing is clearly chosen.", "For a designer, Contempt shows how far a strict, limited palette can go. Using only [[Red|red]], [[Yellow|yellow]] and blue, set against white walls and open sky, every object that carries one of them becomes a sign you notice."], "images": [{"src": "img/films/contempt-r1.jpg", "w": 900, "h": 675, "alt": "A red, box-shaped house perched on a rocky headland above a deep blue sea.", "caption": "Casa Malaparte on Capri, the red masonry house where the Capri scenes were shot. A photo of the real house (2021), not a still.", "credit": "Wolfgang Moroder · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Villa_Malaparte_lato_Est_a_Capri.jpg"}, {"src": "img/films/contempt-r2.jpg", "w": 900, "h": 596, "alt": "The flat, empty roof deck of Casa Malaparte, looking out at rock stacks in a hazy sea.", "caption": "The roof deck of Casa Malaparte, where Camille wears her yellow robe in the film. A 1991 photo of the real house, not a still.", "credit": "Eoghanacht · CC0", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": "https://commons.wikimedia.org/wiki/File:Casa-Malaparte-Capri-Italy_1991-May_04.jpg"}], "colors": [{"name": "Red", "h": "#D62F2F", "app": "Red", "note": "The opening filter, the producer's sports car, the Malaparte walls"}, {"name": "Yellow", "h": "#F2C81F", "app": "Yellow", "note": "Camille's robe on the Capri rooftop"}, {"name": "Mediterranean blue", "h": "#1F6FB2", "app": "Azure", "note": "The second filter on Bardot, and the sea in the final shot"}, {"name": "Brick red", "h": "#A03623", "app": "Brick", "note": "Casa Malaparte's red masonry above the sea"}], "facts": [{"label": "Cinematography", "value": "Raoul Coutard"}, {"label": "Process", "value": "CinemaScope, Technicolor"}, {"label": "Locations", "value": "Cinecittà, Rome; Casa Malaparte, Capri"}, {"label": "Source", "value": "Alberto Moravia's novel Il disprezzo (1954)"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Contempt_(film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/239-contempt"}], "sources": ["https://en.wikipedia.org/wiki/Contempt_(film)", "https://www.criterion.com/current/posts/240-contempt-the-story-of-a-marriage", "https://www.asharperfocus.com/Contempt.html", "https://en.wikipedia.org/wiki/Casa_Malaparte"]},
{"id": "red-desert", "title": "Red Desert (Il deserto rosso)", "year": 1964, "director": "Michelangelo Antonioni", "country": "Italy / France", "dek": "Antonioni's first color film, where he painted the real world grey to show a woman's state of mind.", "body": ["Red Desert was Michelangelo Antonioni's first film in color, and he refused to simply record the colors in front of the camera. He said he wanted to paint the film the way one paints a canvas, inventing the color relationships himself. Monica Vitti plays Giuliana, a woman adrift in the factories, smoke and polluted marshes around Ravenna.", "So he painted reality. Trees and grass were painted white or grey to fit his vision of the industrial landscape. A 1965 TIME report described whole fields and streets sprayed with pigment, and one street scene in which a vendor, his cart and his fruit all turn grey. The fruit is the detail most people remember: food, the most alive thing on a street, made the color of cement.", "Against that grey, the factory colors shout. Pipes, railings and machinery come in hard industrial reds and blues. Critic Andrew Sarris called it an architecture of anxiety. Cinematographer Carlo Di Palma used long telephoto and zoom lenses, which flatten space so that people seem pressed against walls of color.", "The one clear escape is a story Giuliana tells her son. It was filmed on Budelli, a small island off Sardinia known for its pink sand, with clean sea and natural color, the only world in the film that has not been dulled. The lesson for a designer is that [[Grey|grey]] is a choice. Desaturate almost everything, and the few strong colors that remain, the [[Vermilion|reds]] and [[Cobalt|blues]] of the machinery, carry all the feeling."], "images": [{"src": "img/films/red-desert-r1.jpg", "w": 900, "h": 510, "alt": "Aerial view of Ravenna's port: a long canal lined with industrial plants, flat land and sea.", "caption": "The port of Ravenna from the air, with its long industrial canal. The film is set among the factories and marshes around Ravenna. A real photo (2010), not a still.", "credit": "Marek Ślusarczyk (Tupungato) · CC BY 3.0", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Seaport_in_Ravenna,_Italy.jpg"}, {"src": "img/films/red-desert-r2.jpg", "w": 900, "h": 603, "alt": "Silhouettes of port cranes and silos against an orange sunset, a small boat in the foreground.", "caption": "Cranes and silos at the port of Ravenna at sunset. A real photo of the place, not a still.", "credit": "Simone Masini · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Ravenna-tramonto-al-porto.jpg"}, {"src": "img/films/red-desert-r3.jpg", "w": 900, "h": 416, "alt": "A curving beach of pale pink sand on a turquoise bay, framed by green scrub.", "caption": "The pink beach on Budelli, off Sardinia, where the film shot Giuliana's story for her son. A photo of the real island (2009), not a still.", "credit": "Luca Giudicatti (trevis_lu) · CC BY-SA 2.0", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Spiaggia_rosa,_isola_di_budelli,_sardegna.jpg"}], "colors": [{"name": "Ash grey", "h": "#9A9A94", "app": "Grey", "note": "The painted fruit, street and trees: life drained to the color of cement"}, {"name": "Industrial red", "h": "#C8321E", "app": "Vermilion", "note": "Pipes and railings that stand out sharply against the grey"}, {"name": "Industrial blue", "h": "#1F4FA0", "app": "Cobalt", "note": "Factory blues, the other half of what Sarris called its anxious architecture"}, {"name": "Shell pink", "h": "#F3C9C0", "app": "Baby pink", "note": "The pink-sand beach of the fable, the only untouched color"}], "facts": [{"label": "Cinematography", "value": "Carlo Di Palma"}, {"label": "Setting", "value": "Industrial Ravenna; fable filmed on Budelli, Sardinia"}, {"label": "Award", "value": "Golden Lion, Venice 1964"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Red_Desert_(film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/1454-red-desert"}], "sources": ["https://en.wikipedia.org/wiki/Red_Desert_(film)", "https://time.com/archive/6874065/cinema-antonioni-in-color/", "https://www.villagevoice.com/2011/08/31/painted-wasteland-antonionis-red-desert-at-bam/", "https://www.criterion.com/films/1454-red-desert"]},
{"id": "the-umbrellas-of-cherbourg", "title": "The Umbrellas of Cherbourg", "year": 1964, "director": "Jacques Demy", "country": "France", "dek": "A sung-through musical where clothes are cut to match the wallpaper, and the town itself was repainted.", "body": ["In The Umbrellas of Cherbourg every line is sung, and every room seems to sing back. Geneviève, played by Catherine Deneuve, works in her mother's umbrella shop and loves Guy, a young mechanic who is sent to fight in Algeria. Demy billed the film as being in color as proudly as he billed it as sung, and he treated the palette as part of the music.", "Three people built that palette together: production designer Bernard Evein, costume designer Jacqueline Moreau and cinematographer Jean Rabier. Evein drew color schemes and wallpaper designs, and Moreau often made clothes to match the walls. In the pink and [[Mint|green]] striped apartment, Geneviève wears a pink sweater and her mother a green coat. In her bedroom, a blue and mauve floral dress almost disappears into blue and purple floral wallpaper. Several accounts say Evein also had shopfronts and doorways in the real town of Cherbourg repainted in stronger, better-matched colors.", "The effect is a person who belongs to her room, which is part of why the ending lands. The last scene takes place at a petrol station in falling snow, and the bright, matched world of the first acts gives way to [[White|white]] and quiet.", "The film also carries a lesson in keeping color. It was shot on Eastmancolor negative, which fades quickly. Demy protected his work by making separate yellow, cyan and magenta separation masters on black-and-white film, which does not fade. In the 1990s Agnès Varda, his widow, used them to bring the original colors back."], "images": [{"src": "img/films/the-umbrellas-of-cherbourg-r1.jpg", "w": 800, "h": 540, "alt": "A grey stone townhouse in Cherbourg with a dark shopfront signed Les Parapluies de Cherbourg.", "caption": "The real shopfront in Cherbourg that its Commons page identifies as the one used for the umbrella shop. A photo of the street today (2013), not a still.", "credit": "Nebbb · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:FacadeParapluiesDeCherbourg.jpg"}], "colors": [{"name": "Candy pink", "h": "#F2A0B8", "app": "Pink", "note": "Striped walls and Geneviève's sweater, matched on purpose"}, {"name": "Mint green", "h": "#A8EBC4", "app": "Mint", "note": "The other stripe, echoed by her mother's coat"}, {"name": "Lemon yellow", "h": "#F7E15A", "app": "Canary", "note": "One of Geneviève's early outfits, echoed by a citron pressé on a date"}, {"name": "Mauve", "h": "#A8778F", "app": "Mauve", "note": "Floral dress and wallpaper in Geneviève's bedroom"}, {"name": "Snow white", "h": "#F7F6F2", "app": "White", "note": "The final petrol-station scene, color drained to snow"}], "facts": [{"label": "Cinematography", "value": "Jean Rabier"}, {"label": "Production design", "value": "Bernard Evein"}, {"label": "Costumes", "value": "Jacqueline Moreau"}, {"label": "Award", "value": "Palme d'Or, Cannes 1964"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Umbrellas_of_Cherbourg"}, {"label": "Criterion", "url": "https://www.criterion.com/films/27933-the-umbrellas-of-cherbourg"}], "sources": ["https://en.wikipedia.org/wiki/The_Umbrellas_of_Cherbourg", "https://bfidatadigipres.github.io/big%20screen%20classics/2022/05/13/umbrellas-of-cherbourg/", "https://www.dwell.com/article/a-love-letter-to-the-technicolor-interiors-in-the-umbrellas-of-cherbourg-c04a71d8", "https://www.anothermag.com/fashion-beauty/11265/the-technicolour-1960s-musical-that-launched-catherine-deneuves-career", "https://www.sensesofcinema.com/2001/cteq/umbrellas/"]},
{"id": "playtime", "title": "Playtime", "year": 1967, "director": "Jacques Tati", "country": "France", "dek": "Tati built a grey glass city, shot it in color to look almost black and white, then let color creep back in.", "body": ["For Playtime, Jacques Tati built his own modern Paris. The set, nicknamed Tativille, went up on land leased from the city in Saint-Maurice, on the southeast edge of Paris. It had its own power plant and approach road, and to save money some facades were giant photographs. Tati shot it on 70mm film with cinematographers Jean Badal and Andréas Winding, so a gag can play out in any corner of the wide frame.", "Tati wanted a film in color that looked as if it were shot in black and white, an idea he had tried in Mon Oncle. So the first half is mostly shades of [[Grey|grey]], [[Steel blue|blue-grey]], black and greyish white: glass, steel, office cubicles and dark suits. Against that, small accents become events. A flashing red light on an office intercom. Diners turned slightly green by a neon sign. A woman in an [[Emerald|emerald]] dress whom other diners, all in dark clothes, find old-fashioned. The only real plants in the city are at a single flower stall. Elsewhere, balconies hold dull plastic ones.", "The second half takes place at the Royal Garden, a restaurant opening before it is finished. As the night goes on, later guests arrive in brighter and more patterned clothes, the building starts to fall apart, and the room turns into a party. Color returns along with loose, human behavior. Many viewers read the film's arc as exactly that: a cold city warmed back up by people.", "For a designer the lesson is that a nearly neutral palette makes even tiny color accents legible, and that you can stage a whole story as a slow increase in saturation."], "colors": [{"name": "Office grey", "h": "#9EA3A8", "app": "Grey", "note": "Glass, steel and suits of the first half"}, {"name": "Blue-grey", "h": "#6F8496", "app": "Steel blue", "note": "The cool cast of Tativille's towers and offices"}, {"name": "Intercom red", "h": "#D62F2F", "app": "Red", "note": "A tiny flashing light that reads like a shout in the grey"}, {"name": "Emerald", "h": "#50C878", "app": "Emerald", "note": "Barbara's dress, seen as out of date among dark clothes"}, {"name": "Neon green", "h": "#7FD08A", "app": "Pistachio", "note": "The greenish cast a neon sign throws on diners"}], "facts": [{"label": "Cinematography", "value": "Jean Badal and Andréas Winding"}, {"label": "Format", "value": "70mm"}, {"label": "Set", "value": "Tativille, built in Saint-Maurice on the edge of Paris"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Playtime"}, {"label": "Criterion", "url": "https://www.criterion.com/films/651-playtime"}], "sources": ["https://en.wikipedia.org/wiki/Playtime", "https://www.criterion.com/films/651-playtime"]},
{"id": "the-color-of-pomegranates", "title": "The Color of Pomegranates", "year": 1969, "director": "Sergei Parajanov", "country": "Soviet Union (Armenia)", "dek": "A poet's life told as a series of living miniatures, with red dye, juice and blood as its thread.", "body": ["The Color of Pomegranates tells the life of Sayat-Nova, an 18th-century Armenian troubadour, without a normal plot. Each scene is a near-still tableau, framed flat to the camera like a page. Parajanov named his model as the Armenian illuminated miniature, and also described the film as a series of Persian miniatures. Cinematographer Suren Shakhbazyan kept the camera mostly fixed, so color and arrangement do the work that camera movement does elsewhere.", "Red is the main thread. Early on, a cut pomegranate bleeds juice into a white cloth. Many writers describe the stain as taking the shape of the borders of the ancient Kingdom of Armenia. The young poet's world is one of wool and dye, and in one scene dyers lift dripping hanks from the vats. Critic Frank Williams reads their colors as those of the Armenian national flag: red, blue and orange. One essay traces a lace veil that moves from white to red to black, a story of innocence, passion and loss told without words.", "Much of it was filmed at real Armenian sites, including Haghpat Monastery, where Sayat-Nova lived as a monk. Their grey and brown stone gives each saturated object a quiet ground. Parajanov designed some costumes himself, including the green dress the Angel wears at the end. Sofiko Chiaureli plays several roles, male and female.", "For a designer, the film is a lesson in placing one strong color on a muted field, and letting it repeat until it carries meaning on its own. [[Crimson|Pomegranate red]] on [[White|white]] cloth is the image people remember."], "images": [{"src": "img/films/the-color-of-pomegranates-r1.jpg", "w": 900, "h": 354, "alt": "Grey stone churches of Haghpat Monastery on a green hillside in Armenia.", "caption": "Haghpat Monastery in Armenia, where Sayat-Nova lived as a monk and where parts of the film were shot. A photo of the real site (2018), not a still.", "credit": "Tiia Monto · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:2018_Haghpat_Monastery.jpg"}, {"src": "img/films/the-color-of-pomegranates-r2.jpg", "w": 640, "h": 900, "alt": "A medieval Armenian manuscript painting of a seated saint writing, framed in gold, red and blue.", "caption": "Saint Matthew by Toros Roslin, 1262: an Armenian illuminated miniature, the art Parajanov named as his model. A manuscript page, not from the film.", "credit": "Toros Roslin · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:T%27oros_Roslin_-_Evangelist_Matthew_Seated_Dipping_Pen_in_Inkwell_-_Google_Art_Project.jpg"}, {"src": "img/films/the-color-of-pomegranates-r3.jpg", "w": 900, "h": 610, "alt": "A ripe pomegranate split open on its branch, showing deep red seeds.", "caption": "A pomegranate split open on the tree, showing the red that runs through the film. A real photo, not a still.", "credit": "GeorgeTan (Flickr) · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Split_pomegranate,_ready_to_feed_the_birds_-_Flickr_-_GeorgeTan_%5E1...INACTIVE_NOW.jpg"}], "colors": [{"name": "Pomegranate red", "h": "#C0172F", "app": "Crimson", "note": "Juice, dye and blood: the film's main color thread"}, {"name": "Linen white", "h": "#F2EEE4", "app": "White", "note": "The cloth that takes the pomegranate stain"}, {"name": "Dyer's blue", "h": "#1F4C9A", "app": "Cobalt", "note": "Wool from the dye vats, read by one critic as flag colors"}, {"name": "Apricot orange", "h": "#F2A23A", "app": "Apricot", "note": "The third vat color in that flag reading"}, {"name": "Monastery stone", "h": "#8E7F71", "app": "Taupe", "note": "The muted ground of real Armenian monasteries"}], "facts": [{"label": "Cinematography", "value": "Suren Shakhbazyan"}, {"label": "Subject", "value": "The poet Sayat-Nova"}, {"label": "Location", "value": "Armenian sites including Haghpat Monastery"}, {"label": "Restoration", "value": "The Film Foundation and Cineteca di Bologna, 2014"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Color_of_Pomegranates"}, {"label": "Criterion", "url": "https://www.criterion.com/films/29219-the-color-of-pomegranates"}], "sources": ["https://en.wikipedia.org/wiki/The_Color_of_Pomegranates", "https://www.criterion.com/current/posts/5639-10-things-i-learned-the-color-of-pomegranates", "https://www.sensesofcinema.com/2017/soviet-cinema/colour-of-pomegranates/"]},
{"id": "cries-and-whispers", "title": "Cries and Whispers", "year": 1972, "director": "Ingmar Bergman", "country": "Sweden", "dek": "Four women in white inside a red house. Bergman builds a whole film from one image he kept seeing.", "body": ["Cries and Whispers follows two sisters, Karin and Maria, keeping watch over a third, Agnes, who is dying, with the servant Anna as the only one who truly comforts her. Bergman said the film grew from an image that kept returning to him: four women dressed in white, whispering together inside a red room.", "He built the whole palette from that picture. The manor's rooms are dressed in deep [[Crimson|crimson]], and the women's white dresses are set against it again and again. Bergman linked the red to a childhood idea of the soul: a faceless figure, black on the outside, standing for shame, and red on the inside. The film makes that idea structural. Scenes do not fade to black; they fade to a full red screen, as if each memory closes into the inside of a body.", "Cinematographer Sven Nykvist ran many photography tests to find balanced combinations of red, white and skin, which is harder than it sounds. A strong red room reflects warm light onto faces, so skin can easily look sunburned or sick. Getting white cloth to stay white against it, and skin to stay human, was the technical heart of the film. It was shot on Eastmancolor at Taxinge-Näsby, a manor in Sweden. Nykvist won the Academy Award for cinematography.", "For a designer, the film shows how far a two-color system can go when it is held with discipline: one color for the setting, one for the people, and [[Black|black]] held in reserve."], "images": [{"src": "img/films/cries-and-whispers-r1.jpg", "w": 900, "h": 644, "alt": "A pale yellow manor house with a white portico, a gravel drive and lawns in summer.", "caption": "Taxinge-Näsby manor in Sweden, where the film was shot in autumn 1971. Outside it is pale yellow; the crimson rooms were dressed for the film. A photo of the real house (2019), not a still.", "credit": "Holger Ellgaard · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Taxinge_slott,_juli_2019.jpg"}], "colors": [{"name": "Crimson", "h": "#DC143C", "app": "Crimson", "note": "The manor's rooms, and the red fades between scenes"}, {"name": "Deep red", "h": "#7A0A1A", "app": "Burgundy", "note": "Shadowed corners of the red rooms"}, {"name": "Nightgown white", "h": "#F5F2EA", "app": "White", "note": "The women's dresses, the second half of Bergman's first image"}, {"name": "Black", "h": "#16171A", "app": "Black", "note": "In Bergman's image of the soul, the outside, standing for shame"}], "facts": [{"label": "Cinematography", "value": "Sven Nykvist (Academy Award)"}, {"label": "Film stock", "value": "Eastmancolor"}, {"label": "Location", "value": "Taxinge-Näsby manor, Sweden, autumn 1971"}, {"label": "Costumes", "value": "Marik Vos (Academy Award nomination)"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Cries_and_Whispers"}, {"label": "Criterion", "url": "https://www.criterion.com/films/237-cries-and-whispers"}], "sources": ["https://en.wikipedia.org/wiki/Cries_and_Whispers", "https://www.criterion.com/films/237-cries-and-whispers"]},
{"id": "the-holy-mountain", "title": "The Holy Mountain", "year": 1973, "director": "Alejandro Jodorowsky", "country": "Mexico / United States", "dek": "An alchemical quest staged in a tower of rainbow, white and gold rooms, then stripped bare at the summit.", "body": ["The Holy Mountain follows a thief who climbs a tower, meets an alchemist, and joins a group of powerful, corrupt people on a quest for immortality. Jodorowsky directed, wrote and starred as the Alchemist, and also worked as set and costume designer, so the color choices come from one hand. Rafael Corkidi was the cinematographer.", "Color works here like the steps of a ritual. When the Thief climbs into the tower, he enters a room painted in bands of the rainbow, with the Alchemist seated at its center and a clear path leading to him. One common reading is that the Thief moves through the spectrum from red toward violet, like a rise through stages of awakening. Other rooms are lined with Tarot images or have spinning floors marked with occult symbols in strong primary colors.", "Black and [[White|white]] carry the change in him. Viewers often note that the Alchemist first appears draped in black and later, when the Thief asks to be transformed, in white. Many of the tower rooms are white or mostly white. The plot's turning point is literal alchemy: the Alchemist turns the Thief's excrement into [[Gold|gold]].", "The last act drops the designed rooms for real mountain landscape, and the film ends by breaking the illusion: the Alchemist tells the camera to zoom back, showing the crew. For a designer, the arc is useful: build intensity with saturated, coded color, then take it away to signal a return to the plain, real world."], "images": [{"src": "img/films/the-holy-mountain-r1.jpg", "w": 505, "h": 900, "alt": "An old Tarot card, The Tower: a crowned tower struck by fire, figures falling, colored in red, blue and yellow.", "caption": "The Tower card from Nicolas Conver's 1760 Tarot of Marseille, a reprint of a real historical deck. The film lines rooms with Tarot images. A card, not from the film.", "credit": "Tarot World Project · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:XVI_LA_MAISON_DE_DIEU_Nicolas_Conver_Tarot_1760.jpg"}, {"src": "img/films/the-holy-mountain-r2.jpg", "w": 694, "h": 900, "alt": "A painting of an old alchemist kneeling in a dark vaulted lab before a glowing flask.", "caption": "Joseph Wright of Derby's The Alchymist (1771), a painting of the alchemy the film's plot turns on. A painting, not from the film.", "credit": "Joseph Wright of Derby · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Joseph_Wright_of_Derby_The_Alchemist.jpg"}], "colors": [{"name": "Spectrum red", "h": "#D62F2F", "app": "Red", "note": "Where the rainbow room's path begins"}, {"name": "Spectrum violet", "h": "#8000FF", "app": "Violet", "note": "The far end of the rainbow, often read as the goal"}, {"name": "Alchemist white", "h": "#F7F6F2", "app": "White", "note": "Robes and rooms of transformation"}, {"name": "Gold", "h": "#FFD700", "app": "Gold", "note": "The alchemical result: waste turned to gold"}, {"name": "Black", "h": "#16171A", "app": "Black", "note": "The Alchemist's first appearance, before the change"}], "facts": [{"label": "Cinematography", "value": "Rafael Corkidi"}, {"label": "Design", "value": "Sets and costumes co-designed by Jodorowsky"}, {"label": "Producer", "value": "Allen Klein (ABKCO), with funds from John Lennon and Yoko Ono"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Holy_Mountain_(1973_film)"}, {"label": "ABKCO Films", "url": "https://www.abkco.com/film/the-holy-mountain/"}], "sources": ["https://en.wikipedia.org/wiki/The_Holy_Mountain_(1973_film)", "https://www.abkco.com/film/the-holy-mountain/", "https://366weirdmovies.com/the-holy-mountain-1973/"]},
{"id": "suspiria", "title": "Suspiria", "year": 1977, "director": "Dario Argento", "country": "Italy", "dek": "A witch story lit through colored velvet and printed by one of Italy's last Technicolor machines.", "body": ["Suspiria follows Suzy, an American ballet student, into a German dance academy run by a coven of witches. Argento wanted color that looked impossible. He said he and his team were trying to reproduce the color of Disney's Snow White. He embraced Technicolor's old reputation for lacking subtle shades and making figures look like cut-out cartoons.", "Two production choices made that possible. First, cinematographer Luciano Tovoli avoided ordinary colored gels for much of the lighting. He shone lamps through screens he built from colored velvets and tissue paper, which ran so hot that cast members worried they might catch fire. Second, the film was shot on Eastman 5254 negative and printed by Technicolor's dye-transfer (imbibition) process in Rome, a method related to the one used for The Wizard of Oz. It was one of the last features printed that way, on Italy's last machine of its kind.", "On screen, the result is light that seems to come from nowhere. The academy is a mix of black, white, pink and red. As Suzy moves deeper into the building, she is wrapped in fogs of saturated [[Crimson|red]] and [[Cobalt|blue]] with no visible source. In one death scene there is a pit of barbed wire glowing an electric [[Cerulean|cerulean]]. The arrival scene at the airport was lit with two large rotating cylinders with colored openings, turning in opposite directions, so color washes over Suzy before anything has happened.", "Tovoli insisted every image be made on set, with no color added in post-production. For a designer, it is a lesson in pure, unmixed hues used for mood rather than realism."], "images": [{"src": "img/films/suspiria-r1.jpg", "w": 851, "h": 900, "alt": "A tall red Late Gothic townhouse with stepped gables and an ornate oriel window, in Freiburg.", "caption": "The Haus zum Walfisch in Freiburg. The academy's red facade in the film was copied from this house and rebuilt on a soundstage. A photo of the real building, not a still.", "credit": "Joergens.mi · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Haus_zum_Walfisch.jpg"}], "colors": [{"name": "Blood red", "h": "#C8102E", "app": "Crimson", "note": "Fog and light with no source, the film's dominant color"}, {"name": "Deep blue", "h": "#1A3FA0", "app": "Cobalt", "note": "The cold partner to the red in the academy's depths"}, {"name": "Electric cerulean", "h": "#0090C8", "app": "Cerulean", "note": "The glowing pit of barbed wire"}, {"name": "Pink", "h": "#F28DB2", "app": "Pink", "note": "Part of the academy's black, white, pink and red scheme"}], "facts": [{"label": "Cinematography", "value": "Luciano Tovoli"}, {"label": "Printing", "value": "Technicolor dye-transfer (imbibition), Rome"}, {"label": "Film stock", "value": "Eastman 5254"}, {"label": "Music", "value": "Goblin, with Dario Argento"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Suspiria"}, {"label": "BFI", "url": "https://www.bfi.org.uk/film/6c628551-5cbd-5024-94e2-c0523f02a69c/suspiria"}], "sources": ["https://en.wikipedia.org/wiki/Suspiria", "https://www.sensesofcinema.com/2015/feature-articles/luciano-tovoli-suspiria/", "https://www.bfi.org.uk/features/hues-out-hell-how-dario-argento-uses-colour"]},
{"id": "days-of-heaven", "title": "Days of Heaven", "year": 1978, "director": "Terrence Malick", "country": "United States", "dek": "A wheat-field tragedy shot mostly in the short window after sunset, with almost no artificial light.", "body": ["Days of Heaven follows a couple and a young girl who flee Chicago around 1916 to harvest wheat on a rich farmer's land in the Texas Panhandle. It was actually filmed in southern Alberta, Canada. Malick and cinematographer Néstor Almendros wanted to keep artificial light to a minimum, and they looked to silent films, early photojournalism, and painters such as Andrew Wyeth and Edward Hopper. Hopper's House by the Railroad, a lone house against open sky, was a named reference.", "The famous choice is time of day. Many key scenes were shot in what crews call magic hour, the stretch after the sun has set but before night falls. Almendros noted it left them about twenty minutes of usable light a day. The sky still glows, but there is no direct sun, so shadows are soft and the color is even: pale [[Beige|wheat]] fields under a sky that is still lit from below the horizon.", "The palette avoids bright, pop colors in favor of muted earth tones, which lets fire carry the film's emotion. In the night scenes, Almendros lit faces with real flame, so the light flickers and stays warm and reddish in a way electric light would not. Near the end, a locust swarm and a burning wheat field turn the soft gold of the harvest into [[Burnt orange|orange]] and black. The locusts were made by dropping peanut shells from helicopters while the actors walked backward, then running the film in reverse.", "Almendros won the Academy Award for cinematography. Haskell Wexler, who shot roughly half of the finished film, was credited only for additional photography."], "images": [{"src": "img/films/days-of-heaven-r1.jpg", "w": 900, "h": 745, "alt": "Hopper's painting of a lone Victorian house behind a railway embankment under a pale sky.", "caption": "Edward Hopper's House by the Railroad (1925), a lone house against open sky that the filmmakers named as a reference. A painting, not from the film.", "credit": "Edward Hopper · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:The_House_by_the_Railroad_by_Edward_Hopper_1925.jpg"}, {"src": "img/films/days-of-heaven-r2.jpg", "w": 893, "h": 900, "alt": "An early 1900s lantern slide of a wheat field stretching to a flat horizon in southern Alberta.", "caption": "A wheat field in southern Alberta, where the film was shot, on a lantern slide from about 1900-1911. A real photo, not a still.", "credit": "Agnes Deans Cameron · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Limitless_Wheatfield_in_Southern_Alberta_(S2004-980_LS).jpg"}], "colors": [{"name": "Wheat", "h": "#E3CC94", "app": "Beige", "note": "The fields under even, shadowless dusk light"}, {"name": "Harvest gold", "h": "#D9A441", "app": "Marigold", "note": "The soft gold of the harvest before the disaster"}, {"name": "Smoke black", "h": "#1E1C1A", "app": "Black", "note": "Burnt fields and smoke at the film's climax"}, {"name": "Fire orange", "h": "#CC5500", "app": "Burnt orange", "note": "Real firelight on faces, and the burning wheat field"}], "facts": [{"label": "Cinematography", "value": "Néstor Almendros (Academy Award); additional photography Haskell Wexler"}, {"label": "Location", "value": "Southern Alberta, Canada, standing in for Texas"}, {"label": "Light", "value": "Mostly natural, much of it at dusk"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Days_of_Heaven"}, {"label": "Criterion", "url": "https://www.criterion.com/films/213-days-of-heaven"}], "sources": ["https://en.wikipedia.org/wiki/Days_of_Heaven", "https://www.criterion.com/films/213-days-of-heaven", "https://nofilmschool.com/natural-lighting-in-days-of-heaven", "https://www.moviemaker.com/mythmaking-with-natural-light-3206/"]},
{"id": "blade-runner", "title": "Blade Runner", "year": 1982, "director": "Ridley Scott", "country": "United States", "dek": "Film noir lighting pushed into the future: smoke, hard backlight, neon and one amber sunset.", "body": ["Blade Runner follows Deckard, a policeman who hunts escaped artificial humans in a rainy, crowded Los Angeles of 2019. Its look borrows from the past. Ridley Scott pointed to Edward Hopper's painting Nighthawks and to the French comic magazine Métal Hurlant. Cinematographer Jordan Cronenweth said Scott felt the photography of Citizen Kane came closest to what he wanted: high contrast, odd angles and shafts of light.", "Smoke is how those shafts were made. In a polluted city, haze made story sense, and light needs something to hit before you can see the beam. The film's signature setup, as Cronenweth described it, pairs warm, soft uplight on faces in the foreground with hard backlight and smoke behind. The result is a mostly dark frame in which pale beams sweep through the air while faces stay warm and human.", "Color comes from sources in the scene. The street set on the Warner Bros. backlot was filled with dozens of neon signs. Some were dimmed to just above the point where they would flicker, while off-camera neon lit the actors at full strength. Inside the Tyrell Corporation, the sun was faked with arc lamps and [[Amber|amber]] gels outside the windows, giving one of the film's few warm, open spaces. To make replicants' eyes seem to glow, a two-way mirror at 45 degrees bounced light along the lens axis, with subtle colored gels.", "For a designer, the lesson is that a dark palette needs a few strong light sources to read. Most of Blade Runner is near [[Black|black]], and the [[Cerise|neon]], amber and beams of light do all the color work."], "images": [{"src": "img/films/blade-runner-r1.jpg", "w": 900, "h": 491, "alt": "Hopper's Nighthawks: a lit diner window at night on a dark, empty street corner.", "caption": "Edward Hopper's Nighthawks (1942), which Ridley Scott pointed to for the film's look. A painting, not from the film.", "credit": "Edward Hopper · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Nighthawks_by_Edward_Hopper_1942.jpg"}, {"src": "img/films/blade-runner-r2.jpg", "w": 548, "h": 900, "alt": "The glass-roofed atrium of the Bradbury Building, with brick walls and black iron staircases.", "caption": "The atrium of the Bradbury Building in Los Angeles, one of the film's real sets. A photo of the building (2017), not a still.", "credit": "Daniel L. Lu · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Interior_of_the_Bradbury_Building_dllu.jpg"}], "colors": [{"name": "Tyrell amber", "h": "#FFB000", "app": "Amber", "note": "Arc lamps and amber gels faking the sun in Tyrell's office"}, {"name": "Neon pink", "h": "#E0306A", "app": "Cerise", "note": "Street neon, much of it dimmed to just above flicker"}, {"name": "Pale backlight", "h": "#DCE3E8", "app": "Ash", "note": "Hard backlight cutting through smoke"}, {"name": "Night black", "h": "#111316", "app": "Black", "note": "The dark ground that every light source plays against"}], "facts": [{"label": "Cinematography", "value": "Jordan Cronenweth"}, {"label": "Production design", "value": "Lawrence G. Paull; concept art by Syd Mead"}, {"label": "Special effects", "value": "Douglas Trumbull and Richard Yuricich"}, {"label": "Sets", "value": "Warner Bros. backlot; Bradbury Building, Los Angeles"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Blade_Runner"}, {"label": "Warner Bros.", "url": "https://www.warnerbros.com/movies/blade-runner"}], "sources": ["https://en.wikipedia.org/wiki/Blade_Runner", "https://theasc.com/article/blade-runner-cronenweths-photography/", "https://floobynooby.blogspot.com/2011/04/cinematography-of-blade-runner.html"]},
{"id": "ran", "title": "Ran", "year": 1985, "director": "Akira Kurosawa", "country": "Japan / France", "dek": "King Lear as a samurai epic, where three sons are told apart by one primary color each.", "body": ["Ran moves King Lear to 16th-century Japan. An aging warlord, Hidetora, splits his domain among his three sons, and the family destroys itself. Kurosawa, who had trained as a painter, spent about ten years before the shoot painting storyboards of its shots.", "The film's best-known color idea is also its most practical. Each son has a primary color, carried on his banners and his army's armor: [[Yellow|yellow]] for Taro, the eldest; [[Red|red]] for Jiro, the middle son; and [[Blue|blue]] for Saburo, the youngest and the loyal one. In the huge battle scenes, with hundreds of riders on screen, you can read who is winning from the color of the banners alone. Critics have also read the colors as character: yellow for the weak heir, red for the violent one, blue for the calm and honest one. That is interpretation, but it fits how the film plays.", "Behind the banners, the landscape changes too. The early scenes are lush and green. As the war spreads, the land turns ashen and burnt. For the siege of the third castle, Kurosawa built a real castle on the slopes of Mount Fuji and burned it down, with no miniatures.", "The costumes are a large part of why the color holds. Emi Wada and Kurosawa designed 1,400 uniforms and suits of armor, handmade by master tailors over three years, and Wada won the Academy Award for costume design. For a designer, Ran is a clear case of color as a legend: three hues, used consistently, let a viewer follow a complex system at a glance."], "images": [{"src": "img/films/ran-r1.jpg", "w": 900, "h": 391, "alt": "An Edo-period folding screen crowded with armies, each marked by banners, beside a winding river.", "caption": "An 18th-century screen of the 1575 Battle of Nagashino, with armies marked by their banners. A painting of a real battle, not from the film.", "credit": "Unknown artist (Edo period) · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Nagashino_Kassen_Zu_Byoubu,_Toyota.jpg"}, {"src": "img/films/ran-r2.jpg", "w": 900, "h": 600, "alt": "Snow-capped Mount Fuji rising above dark forest and a broad grass meadow.", "caption": "Mount Fuji above open grassland. Kurosawa built and burned his third castle on its slopes. A real photo (2013), not a still.", "credit": "skyseeker (Flickr) · CC BY 2.0", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Mount_Fuji_from_meadow.jpg"}], "colors": [{"name": "Yellow", "h": "#F2C81F", "app": "Yellow", "note": "Taro, the eldest son: his banners and army"}, {"name": "Red", "h": "#D62F2F", "app": "Red", "note": "Jiro, the middle son: his banners and army"}, {"name": "Blue", "h": "#2563C9", "app": "Blue", "note": "Saburo, the youngest and loyal son: his banners and army"}, {"name": "Ash grey", "h": "#B2BEB5", "app": "Ash", "note": "The burnt, ashen land as the war spreads"}], "facts": [{"label": "Cinematography", "value": "Takao Saito, Shōji (Masaharu) Ueda, Asakazu Nakai"}, {"label": "Costumes", "value": "Emi Wada (Academy Award)"}, {"label": "Costume count", "value": "1,400 handmade uniforms and suits of armor"}, {"label": "Source", "value": "Shakespeare's King Lear"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ran_(film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/754-ran"}], "sources": ["https://en.wikipedia.org/wiki/Ran_(film)", "https://scrapsfromtheloft.com/movies/ran-review-pauline-kael/", "https://crookedmarquee.com/stage8/classic-corner-ran/", "https://www.criterion.com/films/754-ran"]},
{"id": "do-the-right-thing", "title": "Do the Right Thing", "year": 1989, "director": "Spike Lee", "country": "United States", "dek": "One Brooklyn block on the hottest day of summer, painted warm and kept nearly free of blue.", "body": ["Do the Right Thing takes place over one hot summer day on a single block of Stuyvesant Avenue in Bedford-Stuyvesant, Brooklyn, as small tensions build into violence. Heat is the story's engine, and its working title was reportedly Heatwave. Color is how the film makes you feel the temperature.", "Production designer Wynn Thomas reshaped a run-down real block. The crew built new structures, including a Korean grocery, a working pizzeria to serve as Sal's Famous, and a radio station where a burnt-out building had stood. Thomas then changed the street's color scheme, using a lot of red and orange paint to suggest a heatwave.", "Cinematographer Ernest Dickerson matched that on camera. He has said everything was geared toward earth tones and warmer colors, from the brownstone interiors to the pizzeria, and that he limited blues and greens on set because they cool a picture down. Instead of the modern HMI lamps common at the time, he used old-fashioned arc lights to get sunlight hard and bright enough, pouring golden light through windows and onto the street.", "The result is a frame where walls, interiors and clothes lean toward [[Brick|brick]], [[Burnt orange|orange]], amber and [[Mustard|yellow]]. Cool colors are so rare that the eye has almost nowhere to rest, and many viewers feel that as rising pressure. For a designer, the film shows how removing one side of the color wheel can create a feeling, like heat or pressure, more strongly than adding anything."], "images": [{"src": "img/films/do-the-right-thing-r1.jpg", "w": 900, "h": 675, "alt": "A row of brick and brownstone houses with high stoops on a leafy Brooklyn street.", "caption": "Brownstones on Decatur Street in Bedford-Stuyvesant's Stuyvesant Heights district, the neighborhood where the film was shot. A real photo (2013), not a still.", "credit": "Smallbones · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:200_block_Decatur_Brooklyn.JPG"}], "colors": [{"name": "Brick red", "h": "#A03623", "app": "Brick", "note": "Painted walls and brownstones of the block"}, {"name": "Heat orange", "h": "#CC5500", "app": "Burnt orange", "note": "The red and orange paint Wynn Thomas added for the heatwave"}, {"name": "Arc-light amber", "h": "#FFBF00", "app": "Amber", "note": "Hard golden sunlight from old-fashioned arc lamps"}, {"name": "Sun yellow", "h": "#D9A92A", "app": "Mustard", "note": "Part of the warm range Dickerson kept to"}], "facts": [{"label": "Cinematography", "value": "Ernest Dickerson"}, {"label": "Production design", "value": "Wynn Thomas"}, {"label": "Location", "value": "Stuyvesant Avenue, Bedford-Stuyvesant, Brooklyn"}, {"label": "Shot", "value": "July to September 1988"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Do_the_Right_Thing"}, {"label": "Criterion", "url": "https://www.criterion.com/films/286-do-the-right-thing"}], "sources": ["https://en.wikipedia.org/wiki/Do_the_Right_Thing", "https://www.slashfilm.com/1142770/spike-lee-and-ernest-dickerson-didnt-want-do-the-right-thing-to-feel-like-a-documentary/", "https://www.criterion.com/films/286-do-the-right-thing"]},
{"id": "dreams", "title": "Dreams", "year": 1990, "director": "Akira Kurosawa", "country": "Japan, United States", "dek": "Eight dreams, each with its own color world, from a director who first wanted to be a painter.", "body": ["Akira Kurosawa planned to become a painter before he found film, and Dreams shows it. The film is eight short episodes based on his own dreams, and each one is built around a different color idea. Kurosawa drew hundreds of pictures for it. When Criterion restored the film, cinematographer Shoji Ueda brought a folder of those drawings, and the team used them to check exactly which blue or red Kurosawa meant.", "In \"The Peach Orchard\", a boy finds the spirits of his family's felled peach trees dressed as festival dolls on a terraced hillside. The orchard returns in bloom, and the crew scattered the [[Pink|pink]] petals by hand rather than adding them with effects. The color is almost the whole story: a slope of blossom that exists for a moment and is gone.", "In \"Crows\", a young painter steps into Van Gogh's canvases, with Martin Scorsese as Van Gogh. Industrial Light & Magic built the walk through painted fields, so the film's colors become thick, brushed [[Yellow|yellows]] and hard blues. It ends with a flock of crows, a nod to Wheat Field with Crows.", "\"Mount Fuji in Red\" turns color into a warning. Nuclear plants explode, and a man explains that radiation is invisible, so the deadly clouds were colored red, yellow and purple to tell the isotopes apart. One common reading is that this is the film's darkest joke: color that names a danger but cannot stop it."], "images": [{"src": "img/films/dreams-r1.jpg", "w": 900, "h": 431, "alt": "Van Gogh's Wheatfield with Crows: a thickly painted yellow wheat field under a stormy dark blue sky, black crows overhead.", "caption": "Vincent van Gogh's Wheatfield with Crows (1890), the painting the \"Crows\" episode ends on. A painting in the Van Gogh Museum, not from the film.", "credit": "Vincent van Gogh · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Korenveld_met_kraaien_-_s0149V1962_-_Van_Gogh_Museum.jpg"}, {"src": "img/films/dreams-r2.jpg", "w": 900, "h": 675, "alt": "A tiered stand draped in bright red cloth, holding rows of traditional Japanese dolls in court dress.", "caption": "A tiered display of hina dolls for Japan's Girls' Festival in March, also called the Peach Festival. The tree spirits in \"The Peach Orchard\" are dressed as dolls like these. A real photo (2013), not a still.", "credit": "掬茶 · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Hina_Dolls_Display_in_the_Ky%C5%8Ddo-no-mori_Park_20130310.jpg"}], "colors": [{"name": "Peach blossom pink", "h": "#F7C6D0", "app": "Baby pink", "note": "The orchard in bloom, returned for one last look"}, {"name": "Chrome yellow", "h": "#FFA700", "app": "Marigold", "note": "The brushed wheat fields of the Van Gogh episode"}, {"name": "Red", "h": "#D62F2F", "app": "Red", "note": "The sky over Mount Fuji and one of the poison clouds"}, {"name": "Purple", "h": "#7B3FA0", "app": "Purple", "note": "Another colored cloud: color used as a label for danger"}], "facts": [{"label": "Cinematography", "value": "Takao Saito, Shoji Ueda"}, {"label": "Art direction", "value": "Yoshiro Muraki"}, {"label": "Visual effects", "value": "Industrial Light & Magic"}, {"label": "Van Gogh played by", "value": "Martin Scorsese"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dreams_(1990_film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/28700-akira-kurosawa-s-dreams"}], "sources": ["https://en.wikipedia.org/wiki/Dreams_(1990_film)", "https://www.criterion.com/current/posts/3862-the-color-of-dreams", "https://www.criterion.com/films/28700-akira-kurosawa-s-dreams", "https://en.wikipedia.org/wiki/Akira_Kurosawa"]},
{"id": "raise-the-red-lantern", "title": "Raise the Red Lantern", "year": 1991, "director": "Zhang Yimou", "country": "China, Hong Kong", "dek": "In a grey stone compound, one color decides who matters each night: lantern red.", "body": ["Raise the Red Lantern is set in a wealthy family's walled compound in Republican-era China. Songlian, played by Gong Li, becomes the fourth wife of a master whose face the film never shows clearly. Each evening his choice is announced with lanterns. The chosen wife's house is hung with them, and she gets a foot massage, her pick of the menu and the servants' respect.", "That ritual was invented for the film. It is not in Su Tong's novella, and some Chinese critics attacked it as false history. As a color idea, though, it is very clear. The compound, shot at the Qiao family courtyards in Shanxi, is all [[Grey|grey]] brick, roof tiles and narrow alleys. Against it, the lanterns are the only strong warm color, so the eye reads red as favor, warmth and power before anyone explains the rules.", "Cinematographer Zhao Fei keeps the women framed inside doorways and courtyards, small against the architecture. The red does the talking. When a wife falls from favor, her lanterns are covered with [[Black|black]] cloth bags, and the color is taken away rather than replaced.", "The story moves through the seasons, and by winter the courtyards fill with snow. A designer can learn a lot from how little the film uses: one saturated hue, a field of neutrals around it, and meaning that comes from where the red is allowed to appear."], "images": [{"src": "img/films/raise-the-red-lantern-r1.jpg", "w": 900, "h": 629, "alt": "A narrow grey-brick courtyard with carved wooden doorways, hung with rows of red lanterns.", "caption": "A courtyard of the Qiao family compound in Shanxi, where the film was shot: grey brick and tile, with red lanterns the only strong color. A photo of the real place (2011), not a still.", "credit": "Francisco Anzola · CC BY 2.0", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Qio_family_courtyard_(6243046177).jpg"}, {"src": "img/films/raise-the-red-lantern-r2.jpg", "w": 900, "h": 675, "alt": "A carved grey brick gateway with a dark plaque, every surface covered in relief decoration.", "caption": "A carved brick gateway in the Qiao family compound, the grey architecture that surrounds every red in the film. A real photo (2016), not a still.", "credit": "lienyuan lee · CC BY 3.0", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Qiao_Family_Compound_%E5%96%AC%E5%AE%B6%E5%A4%A7%E9%99%A2_-_panoramio_-_lienyuan_lee.jpg"}], "colors": [{"name": "Lantern red", "h": "#C8102E", "app": "Crimson", "note": "The master's choice: favor, warmth and rank in one color"}, {"name": "Brick grey", "h": "#7D7F7D", "app": "Grey", "note": "The compound's walls and roofs, a neutral field for the red"}, {"name": "Black", "h": "#16171A", "app": "Black", "note": "Cloth bags that cover the lanterns when favor is withdrawn"}, {"name": "Snow white", "h": "#F2F3F0", "app": "White", "note": "Winter in the courtyards, when the house turns cold"}], "facts": [{"label": "Cinematography", "value": "Zhao Fei"}, {"label": "Based on", "value": "Wives and Concubines, a 1990 novella by Su Tong"}, {"label": "Filmed at", "value": "Qiao family compound near Pingyao, Shanxi"}, {"label": "Award", "value": "Nominated for the Oscar for Best Foreign Language Film"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Raise_the_Red_Lantern"}, {"label": "BFI", "url": "https://www.bfi.org.uk/film/d4bb41b5-d42a-5555-8430-d875e297d329/raise-the-red-lantern"}], "sources": ["https://en.wikipedia.org/wiki/Raise_the_Red_Lantern", "https://www.sensesofcinema.com/2018/feature-articles/zhang-yimou-cultural-politics/", "https://en.wikipedia.org/wiki/Raise_the_Red_Lantern_(novella)", "https://www.deepfocusreview.com/definitives/raise-the-red-lantern/"]},
{"id": "three-colours-blue", "title": "Three Colours: Blue", "year": 1993, "director": "Krzysztof Kieślowski", "country": "France, Poland, Switzerland", "dek": "A grieving woman tries to be free of everything, and a color keeps finding her anyway.", "body": ["Blue opens Kieślowski's trilogy named after the French flag. The three films are loosely tied to liberty, equality and fraternity, but he treated those ideals with irony, and he liked to say the colors were French because the money was French. Had the funding come from Germany, he joked, the films might have been Black, Red and Yellow.", "Julie, played by Juliette Binoche, loses her husband and young daughter in a car crash. She tries to cut every tie and start an anonymous life in Paris. The color is how the past leaks back in. She empties her daughter's blue room but keeps one thing, a hanging lamp of [[Cobalt|blue]] glass beads, and hangs it in her new flat. She finds a blue lollipop among her daughter's things and bites it to pieces.", "Cinematographer Sławomir Idziak used blue filters and gels in several scenes where Julie is alone, so the color often reads as her inner state rather than a real light source. Some scenes go further. As fragments of her husband's unfinished music rise up in her, the screen fades fully to [[Black|black]] and then back to Julie, as if the world pauses. She also swims alone in a pool that glows an intense [[Azure|blue]].", "Critics often note that the meaning of the color shifts. Early on it reads as grief. By the end, as Julie returns to the music, many read the same blue as a sign she is ready to live again. The lesson for designers: one color can carry a whole arc if its meaning is allowed to change."], "images": [{"src": "img/films/three-colours-blue-r1.jpg", "w": 675, "h": 900, "alt": "The blue, white and red French tricolor flying against a deep blue sky above a classical stone building in Paris.", "caption": "The French flag over the Hôtel de la Marine in Paris. Its three colors name the trilogy: blue, white, red. A real photo (2012), not a still.", "credit": "Acediscovery · CC BY 4.0", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0", "commons": "https://commons.wikimedia.org/wiki/File:France-flag-Hotel-de-la-Marine-Paris.jpg"}], "colors": [{"name": "Glass bead blue", "h": "#1F4FB5", "app": "Cobalt", "note": "The daughter's lamp, the one object Julie keeps"}, {"name": "Pool blue", "h": "#1E90FF", "app": "Azure", "note": "The pool where Julie swims alone, sinking into the color"}, {"name": "Black", "h": "#16171A", "app": "Black", "note": "Full fades when the music returns and the world pauses"}], "facts": [{"label": "Cinematography", "value": "Sławomir Idziak"}, {"label": "Music", "value": "Zbigniew Preisner, written before shooting began"}, {"label": "Award", "value": "Golden Lion, Venice Film Festival 1993"}, {"label": "Trilogy theme", "value": "Liberty"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Three_Colours:_Blue"}, {"label": "Criterion", "url": "https://www.criterion.com/films/27731-three-colors-blue"}], "sources": ["https://en.wikipedia.org/wiki/Three_Colours:_Blue", "https://en.wikipedia.org/wiki/Three_Colours_trilogy", "https://www.criterion.com/current/posts/5599-10-things-i-learned-three-colors", "https://www.sensesofcinema.com/2007/cteq/three-colours-blue/", "http://www.classicartfilms.com/three-colors-blue-1993"]},
{"id": "chungking-express", "title": "Chungking Express", "year": 1994, "director": "Wong Kar-wai", "country": "Hong Kong", "dek": "Shot in 23 days with whatever light the city gave: neon, street lamps and snack-bar tubes.", "body": ["Wong Kar-wai made Chungking Express quickly, during a two-month break from editing another film. Cinematographer Christopher Doyle has said it was shot in 23 days, often in the busiest parts of Hong Kong, fast and improvised. Doyle's own flat became the home of one of the two lovesick cops. That speed shaped the color. Instead of building lighting, the crew mostly worked with what was there: daylight from a window, street lamps, shop signs and overhead tubes.", "The film has two stories, and they feel different. The first runs at night around the crowded Chungking Mansions, where a drug smuggler in a blonde wig, trench coat and sunglasses moves through neon and shadow. Parts are step-printed, so movement smears into streaks of colored light. The wig works like a graphic mark: one pale shape you can follow through a dark, busy frame.", "The second story spends more time in daylight, around the Midnight Express snack bar where Faye works. It plays brighter and looser. Under strip lights, some scenes take on a cool cast, a common look when fluorescent tubes are filmed without correction, and the result feels everyday rather than glamorous.", "The colors you see today depend on the version. For the 2021 restorations, Wong regraded his films and restored Chungking Express to its intended 1.66:1 frame. Some fans objected to the new colors. Wong's answer was that these are not the same films, and the audience is not the same either."], "images": [{"src": "img/films/chungking-express-r1.jpg", "w": 900, "h": 629, "alt": "The tall facade of Chungking Mansions at night, its windows lit in green and white above glowing shop signs.", "caption": "Chungking Mansions on Nathan Road at night, the crowded building the film's first story moves through. A real photo (2013), not a still.", "credit": "Matthäus Wander · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Chungking_Mansions_Front_at_Night_(2013).jpg"}, {"src": "img/films/chungking-express-r2.jpg", "w": 900, "h": 599, "alt": "The busy street entrance of Chungking Mansions, crowded with people under bright red, green and pink shop signs.", "caption": "The ground-floor entrance of Chungking Mansions by day, a wall of shop signs. A real photo (2011), not a still.", "credit": "chensiyuan · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:1_chungking_mansions_2011.JPG"}], "colors": [{"name": "Blonde", "h": "#E3C878", "app": "Khaki", "note": "The smuggler's wig, one pale mark to follow through crowds"}, {"name": "Neon red", "h": "#FF2E2E", "app": "Scarlet", "note": "Shop signs that smear into streaks in step-printed chases"}, {"name": "Fluorescent green", "h": "#B9D9A6", "app": "Celadon", "note": "The cool, everyday cast of strip-lit scenes"}], "facts": [{"label": "Cinematography", "value": "Christopher Doyle, Andrew Lau"}, {"label": "Production design", "value": "William Chang"}, {"label": "Shoot", "value": "23 days, largely on location (per Doyle)"}, {"label": "Aspect ratio", "value": "1.66:1, restored in 2021"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Chungking_Express"}, {"label": "Criterion", "url": "https://www.criterion.com/films/226-chungking-express"}], "sources": ["https://en.wikipedia.org/wiki/Chungking_Express", "https://www.bfi.org.uk/interviews/christopher-doyle-shooting-chungking-express", "https://www.criterion.com/current/posts/7325-world-of-wong-kar-wai-director-s-note", "https://midwestfilmjournal.com/2025/04/07/on-criterion-chungking-express-4k-uhd/"]},
{"id": "three-colours-red", "title": "Three Colours: Red", "year": 1994, "director": "Krzysztof Kieślowski", "country": "France, Poland, Switzerland", "dek": "Red threads through Geneva like a hidden wire, linking strangers who have not met yet.", "body": ["Red closes Kieślowski's trilogy named for the French flag, and it is the film loosely tied to fraternity. Valentine, played by Irène Jacob, is a student and model in Geneva. After she hits a dog with her car, she meets its owner, a retired judge who listens in on his neighbors' phone calls. Across the street lives a young law student whose life keeps nearly crossing hers.", "Here the color is mostly in objects, not filters. Valentine poses for a chewing gum billboard in profile against a wall of pure [[Scarlet|red]]. The poster then hangs over the street for much of the film. Red turns up again and again in small things, like the cherries on a slot machine. Because it appears in both Valentine's world and the law student's, the eye starts to connect two people who have not met. Critics often read the repeated red as the film's way of showing ties between strangers.", "The look grew out of the ending. Cinematographer Piotr Sobociński decided that one image should shape the whole film: Irène Jacob seen against the [[Vermilion|red]] coat of a ferry rescue worker. In the last scene, Valentine survives a ferry disaster, and a TV camera catches her in profile with a red jacket behind her. It repeats the billboard almost exactly.", "For a designer, Red shows how a single hue can work as a thread. Scatter it across unrelated scenes and viewers will start to treat those scenes as connected."], "images": [{"src": "img/films/three-colours-red-r1.jpg", "w": 900, "h": 600, "alt": "A sunny square in Geneva's old town with stone buildings, trees and a few cyclists.", "caption": "The old town of Geneva, the city where Valentine lives in the film. A real photo (2025), not a still.", "credit": "karlheinz klingbeil · CC BY 4.0", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Geneva_old_town_2025.jpg"}], "colors": [{"name": "Billboard red", "h": "#E0201B", "app": "Scarlet", "note": "The backdrop of Valentine's gum ad, hung over the street"}, {"name": "Cherry red", "h": "#C41E3A", "app": "Crimson", "note": "Small props, like slot machine cherries, that echo the poster"}, {"name": "Rescue jacket red", "h": "#E34234", "app": "Vermilion", "note": "The final shot that repeats the billboard pose"}], "facts": [{"label": "Cinematography", "value": "Piotr Sobociński"}, {"label": "Music", "value": "Zbigniew Preisner"}, {"label": "Oscar nominations", "value": "Director, Original Screenplay, Cinematography"}, {"label": "Trilogy theme", "value": "Fraternity"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Three_Colours:_Red"}, {"label": "Criterion", "url": "https://www.criterion.com/films/27733-three-colors-red"}], "sources": ["https://en.wikipedia.org/wiki/Three_Colours:_Red", "https://www.criterion.com/current/posts/5599-10-things-i-learned-three-colors", "http://1001moviesblog.blogspot.com/2014/06/three-colors-red-trois-couleurs-rouge.html", "https://www.asharperfocus.com/Red.html"]},
{"id": "three-colours-white", "title": "Three Colours: White", "year": 1994, "director": "Krzysztof Kieślowski", "country": "France, Poland, Switzerland", "dek": "The comic middle film of the trilogy, where white shows up as light: glare, snow and memory.", "body": ["White is the second film in Kieślowski's trilogy named for the colors of the French flag, and it is the one tied, loosely and with irony, to equality. Roger Ebert called the three films an anti-tragedy, an anti-comedy and an anti-romance, and White is the anti-comedy. Karol Karol, a Polish hairdresser, is divorced by his French wife Dominique, played by Julie Delpy. He loses everything in Paris, gets smuggled home to Warsaw in a suitcase, gets rich, and plots an elaborate revenge.", "White is a harder color to build a film around than blue or red, because it barely reads as a color at all. Cinematographer Edward Kłosiński mostly shows it as light. The memory of the wedding is a soft, glowing flashback in which Dominique in her dress steps out of a church into a blaze of overexposed [[White|white]]. Warsaw is wintry, with snow and pale skies, against the drabber [[Grey|grey]] of Paris.", "One white object follows Karol through the story: a plaster bust of a woman that reminds him of Dominique. He carries it from Paris and treats it tenderly, a cold stand-in for the person he cannot reach. Critics often read the film's white as a blank, like a wedding dress or fresh snow, that the characters keep trying to write on.", "For a designer, White is a useful study. When a palette has no strong hue, meaning comes from value and glare: how bright a white is, how washed out, and what is around it."], "images": [{"src": "img/films/three-colours-white-r1.jpg", "w": 900, "h": 600, "alt": "A Warsaw street at dusk in January, with heaps of grey snow and pale light under a cold sky.", "caption": "Warsaw in January snow, the wintry city Karol goes home to in the film. A real photo (2018), not a still.", "credit": "Rakoon · CC0", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": "https://commons.wikimedia.org/wiki/File:DSC-1787-warsaw-poland-january-2018.jpg"}], "colors": [{"name": "Overexposed white", "h": "#F7F6F2", "app": "White", "note": "The glowing wedding memory, almost too bright to see"}, {"name": "Plaster white", "h": "#ECE6D8", "app": "Ecru", "note": "The bust Karol carries as a stand-in for Dominique"}, {"name": "Winter grey", "h": "#A7ABAE", "app": "Silver", "note": "Pale skies and snow-light in Warsaw"}], "facts": [{"label": "Cinematography", "value": "Edward Kłosiński"}, {"label": "Music", "value": "Zbigniew Preisner"}, {"label": "Award", "value": "Silver Bear for Best Director, Berlin 1994"}, {"label": "Trilogy theme", "value": "Equality"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Three_Colours:_White"}, {"label": "Criterion", "url": "https://www.criterion.com/films/27732-three-colors-white"}], "sources": ["https://en.wikipedia.org/wiki/Three_Colours:_White", "https://en.wikipedia.org/wiki/Three_Colours_trilogy", "https://www.asharperfocus.com/White.html", "https://filmotomy.com/1994-in-film-the-double-couleurs-of-krzysztof-kieslowski-with-white-and-red/"]},
{"id": "pixar-color-scripts", "title": "Pixar color scripts", "year": 1995, "director": "Pixar Animation Studios", "country": "United States", "dek": "A whole film's color, planned as a strip of small paintings before anything is animated.", "body": ["A color script is a sequence of small, loose paintings that maps how a film's color, light and mood will change from scene to scene. Think of it as a storyboard for feeling instead of action. Pixar did not invent the idea, but it became known as the first studio to make a color script for every one of its films.", "Ralph Eggleston, art director on Toy Story, brought the practice to Pixar and made its first one, for Toy Story (1995), in pastel. Pastel stuck for years because it is fast. Speed matters, because computer animation is made out of order, and the director needs early clues about what the finished frames will look like. Eggleston's pastel scripts are known for soft blues, bubblegum [[Pink|pinks]] and warm yellows.", "Eggleston said he would start by doodling little blobs of color, looking for the story in the emotions the colors suggested. He later designed Finding Nemo and WALL-E, and for WALL-E, his first color script made digitally, he pitched lighting the robot and the first act on Earth in classically romantic terms, because WALL-E is a romantic.", "Other artists brought their own styles. Lou Romano's digital scripts for The Incredibles and Up use abstract shapes and bright colors with a 1960s pop-art feel. A color script will not make or break a film, but it lets the whole crew see the emotional arc at a glance. For any designer, it is a useful habit: plan how color changes over time, not just what each screen looks like."], "images": [{"src": "img/films/pixar-color-scripts-r1.jpg", "w": 900, "h": 865, "alt": "A red plastic cabinet of drawers holding rows of soft pastel sticks in many colors.", "caption": "A set of soft pastels, the quick medium Ralph Eggleston used for Pixar's first color scripts. A photo of the art supplies, not Pixar artwork.", "credit": "W.carter · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:A_set_of_Winsor_%26_Newton_soft_pastel_crayons.jpg"}], "colors": [{"name": "Soft pastel blue", "h": "#A9C8E8", "app": "Powder blue", "note": "A recurring note in Eggleston's pastel scripts"}, {"name": "Bubblegum pink", "h": "#F7A1C4", "app": "Pink", "note": "Eggleston's warm, playful pastel accent"}, {"name": "Warm yellow", "h": "#F6C94C", "app": "Yellow", "note": "Pastel warmth that maps the cozy moments"}, {"name": "Pop-art orange", "h": "#F28500", "app": "Tangerine", "note": "The zingy 1960s pop feel of Lou Romano's scripts"}], "facts": [{"label": "First Pixar color script", "value": "Toy Story (1995), by Ralph Eggleston, in pastel"}, {"label": "Ralph Eggleston", "value": "Art director, Toy Story; production designer, Finding Nemo and WALL-E"}, {"label": "Lou Romano", "value": "Color scripts for The Incredibles and Up"}, {"label": "Book", "value": "The Art of Pixar (2011), by Amid Amidi, collects the color scripts"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ralph_Eggleston"}, {"label": "MoMA", "url": "https://www.moma.org/audio/playlist/192/2581"}], "sources": ["https://animatedviews.com/2011/the-art-of-pixar-the-complete-color-scripts-and-select-art-from-25-years-of-animation-an-interview-with-author-amid-amidi/", "https://hyperallergic.com/the-art-of-pixar-chronicle-books/", "https://www.animationartconservation.com/design-with-a-purpose,-an-interview-with-ralph-eggleston.html", "https://en.wikipedia.org/wiki/Ralph_Eggleston"]},
{"id": "in-the-mood-for-love", "title": "In the Mood for Love", "year": 2000, "director": "Wong Kar-wai", "country": "Hong Kong", "dek": "Two neighbors who never quite act, a new dress for every day, and a hotel corridor hung in red.", "body": ["In Hong Kong in 1962, Mrs. Chan and Mr. Chow move into neighboring rooms on the same day and slowly realize their spouses are having an affair with each other. The film is about what they feel and do not do, and much of that is carried by color and fabric rather than words.", "William Chang designed the sets, the costumes and the makeup, so one eye controlled every surface. Maggie Cheung wears a different high-collared cheongsam, more than twenty in all, almost every time she appears. Because the cramped rooms and stairways barely change, Wong has said that a new dress is often how you know another day has passed. He described each dress as her mood for that day. Writers on the film often note how the dress patterns echo, or clash with, the wallpaper behind her.", "Against all that pattern, [[Crimson|red]] is held back for charged places. The two meet to write together in a hotel whose corridor is lined with deep red curtains, and Mrs. Chan wears a red raincoat there. Critics often read the red as desire that is visible but never acted on. The camera also shoots through curtains, smoke, rain and smeared mirrors, so color often reaches you softened, as if remembered.", "Christopher Doyle began as cinematographer and Mark Lee Ping-bing took over when the shoot ran long, about 15 months in all. The 2020 restoration, approved by Wong, changed the color grading of some of his films, so older and newer versions of this one can look different."], "images": [{"src": "img/films/in-the-mood-for-love-r1.jpg", "w": 550, "h": 900, "alt": "A fitted high-collared cheongsam in printed velvet with a dense multicolored pattern, on a museum mannequin against pink.", "caption": "A Hong Kong cheongsam (qipao) in printed velvet from 1960-1970, in the V&A Museum. The film is set in Hong Kong in 1962. A museum photo, not from the film.", "credit": "Ismoon · CC0", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": "https://commons.wikimedia.org/wiki/File:Qipao_1960-70,_printed_velvet._V%26A_Museum.jpg"}, {"src": "img/films/in-the-mood-for-love-r2.jpg", "w": 900, "h": 506, "alt": "Three cheongsams on mannequins in glass cases, in a Hong Kong Museum of History exhibition at the airport.", "caption": "Cheongsams in a Hong Kong Museum of History exhibition (2018). A real photo of the dresses, not a still.", "credit": "Donald Trung · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Hong_Kong_Museum_of_History_Cheongsam_exhibition,_Hong_Kong_International_Airport_(2018)_01.jpg"}], "colors": [{"name": "Curtain red", "h": "#9B111E", "app": "Carmine", "note": "The hotel corridor where the two meet to write"}, {"name": "Raincoat red", "h": "#C8102E", "app": "Crimson", "note": "Mrs. Chan's coat, matching the hotel's curtains"}, {"name": "Floral magenta", "h": "#B8336A", "app": "Mulberry", "note": "Patterned cheongsams: each new dress marks a new day"}], "facts": [{"label": "Cinematography", "value": "Christopher Doyle, Mark Lee Ping-bing"}, {"label": "Production and costume design", "value": "William Chang"}, {"label": "Award", "value": "Cannes 2000: Best Actor (Tony Leung) and the Technical Grand Prize"}, {"label": "Shoot", "value": "About 15 months, partly in Bangkok"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/In_the_Mood_for_Love"}, {"label": "Criterion", "url": "https://www.criterion.com/films/198-in-the-mood-for-love"}], "sources": ["https://en.wikipedia.org/wiki/In_the_Mood_for_Love", "https://classiq.me/style-in-film-maggie-cheung-in-in-the-mood-for-love", "https://offscreen.com/view/gendering-in-the-mood-for-love-2000-wong-kar-wai-hong-kong", "https://www.criterion.com/current/posts/7325-world-of-wong-kar-wai-director-s-note"]},
{"id": "amelie", "title": "Amélie", "year": 2001, "director": "Jean-Pierre Jeunet", "country": "France, Germany", "dek": "A storybook Paris built from three colors, a warm filter and an early digital grade.", "body": ["Amélie's Montmartre looks like a real place turned into a storybook, and that was the plan. The film's whole palette rests on three colors: red, green and a warm gold-yellow. It took cues from the saturated paintings of Juarez Machado, a Brazilian artist who lived in Paris and was a friend and neighbor of Jeunet's.", "The look was built in two stages. On set, cinematographer Bruno Delbonnel shot through a warm filter, so the image already leaned toward yellow. Then the film was digitally color graded and recorded back to film, which was still unusual in 2001. The grade pushed [[Red|reds]], greens and [[Mustard|mustard]] yellows and kept cool tones down.", "The palette works because it is limited. Red and green are a classic contrasting pair, so side by side each looks stronger, and a gold cast ties them together like old varnish. With blues held back, the screen has almost no cool place for the eye to rest, which helps the film feel warm and slightly unreal.", "Jeunet also edited the city itself. Graffiti, bins and grime were cleared away, often with digital effects. Some critics called the result a cleaned-up Paris that never existed. For a designer, it is a clear lesson in how much a world's mood comes from what you leave out."], "images": [{"src": "img/films/amelie-r1.jpg", "w": 900, "h": 616, "alt": "The red-awninged Café des 2 Moulins on a Montmartre corner, with people at its terrace tables.", "caption": "The Café des 2 Moulins on rue Lepic in Montmartre, the real café where Amélie works in the film. Its red awning sits in the film's own palette. A real photo (2010), not a still.", "credit": "Aleksandr Zykov · CC BY-SA 2.0", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0", "commons": "https://commons.wikimedia.org/wiki/File:Caf%C3%A9_des_2_Moulins_June_2010.jpg"}], "colors": [{"name": "Red", "h": "#D62F2F", "app": "Red", "note": "The strongest accent, set against green to make both pop"}, {"name": "Olive green", "h": "#6B7A2A", "app": "Olive", "note": "The green half of the pair, warmed by the gold grade"}, {"name": "Mustard", "h": "#CFA41C", "app": "Mustard", "note": "The golden cast that ties the palette together"}], "facts": [{"label": "Cinematography", "value": "Bruno Delbonnel (Oscar-nominated)"}, {"label": "Production design", "value": "Aline Bonetto (Oscar-nominated)"}, {"label": "Palette inspiration", "value": "Paintings by Juarez Machado"}, {"label": "Process", "value": "Warm camera filter plus a digital color grade"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Am%C3%A9lie"}, {"label": "BFI", "url": "https://www.bfi.org.uk/film/2828d25a-1b4d-517f-9da7-99cac2e45c2e/amelie"}], "sources": ["https://en.wikipedia.org/wiki/Am%C3%A9lie", "https://apollo-magazine.com/amelie-film-jean-pierre-jeunet-25-cgi-special-effects/", "https://en.wikipedia.org/wiki/Juarez_Machado", "https://www.modernmotionvideo.com/cinema-blog/learning-from-the-masters-amelie"]},
{"id": "hero", "title": "Hero", "year": 2002, "director": "Zhang Yimou", "country": "China, Hong Kong", "dek": "One story told three ways, and each telling gets its own color, from costumes to scenery.", "body": ["Hero is often compared to Rashomon, and cinematographer Christopher Doyle made the comparison himself: an unreliable narrator and stories inside stories. A nameless swordsman comes to the palace of the King of Qin and explains how he defeated three assassins. The King doubts him, so the story is told again, and then again. Each version is dressed in its own color.", "The palace scenes in the present are dark and heavy with [[Black|black]]. The swordsman's first account is red. Doyle has linked red to desire and jealousy, blue to reason and friendship, and white to the balance of the two, the final truth. Yet the colors are also reported to have been chosen for their look rather than as symbols, so treat these meanings loosely. The red account includes a duel between two women among whirling golden leaves that turn red as the fight ends. The King's version is blue. The final, true account is white. A memory of an earlier attempt on the King plays in vivid [[Jade|green]].", "Costumes by Emi Wada, sets and even the landscape follow each version. The crew often found locations first, such as the lakes of Jiuzhaigou, and then decided which colors to use, rewriting the script to fit. Doyle shot most of the film on Fuji stock but switched to Kodak for the red section, to get a more saturated, solid red. He also said that by the green section they had run out of colors, and that they steered away from pink.", "For designers, Hero shows color used as a filing system: one hue per version of the truth, so the audience can sort the stories without a single caption."], "images": [{"src": "img/films/hero-r1.jpg", "w": 900, "h": 675, "alt": "A clear turquoise lake with sunken tree trunks visible underwater, ringed by autumn trees in orange and green.", "caption": "Five Flower Lake in Jiuzhaigou, Sichuan. The crew chose Jiuzhaigou's lakes first and then fitted the colors to them. A real photo (2012), not a still.", "credit": "Culantor Lin · CC BY-SA 2.0", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0", "commons": "https://commons.wikimedia.org/wiki/File:%E4%B9%9D%E5%AF%A8%E6%BA%9D-%E4%BA%94%E8%8A%B1%E6%B5%B7_Jiuzhaigou_Five_Flower_Lake_1.jpg"}, {"src": "img/films/hero-r2.jpg", "w": 900, "h": 600, "alt": "A long blue lake between steep forested mountains, a snowy peak at the far end.", "caption": "Long Lake in Jiuzhaigou National Park, among the park's mountain lakes. A real photo (2026), not a still.", "credit": "Suicasmo · CC0", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": "https://commons.wikimedia.org/wiki/File:Long_Lake_(Jiuzhaigou)_20260511-1.jpg"}], "colors": [{"name": "Red", "h": "#D62F2F", "app": "Red", "note": "The swordsman's first telling, linked by Doyle to desire"}, {"name": "Golden yellow", "h": "#E8A317", "app": "Marigold", "note": "Whirling leaves in the forest duel, turning red"}, {"name": "Blue", "h": "#2563C9", "app": "Blue", "note": "The King's version of events, linked by Doyle to reason"}, {"name": "Jade green", "h": "#00A86B", "app": "Jade", "note": "A flashback to an earlier attempt on the King"}, {"name": "White", "h": "#F7F6F2", "app": "White", "note": "The final, true telling"}], "facts": [{"label": "Cinematography", "value": "Christopher Doyle"}, {"label": "Costume design", "value": "Emi Wada"}, {"label": "Locations", "value": "Including Jiuzhaigou National Park, Sichuan"}, {"label": "Award", "value": "Oscar nomination, Best Foreign Language Film"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Hero_(2002_film)"}, {"label": "BFI", "url": "https://www.bfi.org.uk/lists/10-great-wuxia-swordplay-films"}], "sources": ["https://en.wikipedia.org/wiki/Hero_(2002_film)", "https://tvtropes.org/pmwiki/pmwiki.php/Film/Hero2002", "https://offscreen.com/view/hero", "https://www.bfi.org.uk/lists/10-great-wuxia-swordplay-films"]},
{"id": "the-tree-of-life", "title": "The Tree of Life", "year": 2011, "director": "Terrence Malick", "country": "United States", "dek": "A childhood lit almost only by the sun, where bright primary colors were kept out of frame.", "body": ["The Tree of Life moves between a 1950s Texas childhood and the birth of the universe. Malick and cinematographer Emmanuel Lubezki worked almost entirely in natural light, mostly with handheld cameras. They reportedly kept a written set of shooting rules, joking that it was their own dogma. Among them: shoot in available light, shoot into backlight, avoid lens flares, and avoid white and primary colors in frame. Like any good rule list, it ended with an exception clause.", "That one color rule explains a lot of the film's look. With no bold red or blue to grab attention, the eye goes to light itself: [[Sky blue|sky]] reflected through windows, grass, skin and wood, often glowing from behind in [[Marigold|golden]] backlight. Lubezki has said that once you light a scene with a window, the room fills with colors bounced from sky, clouds and lawn, and artificial light starts to feel wrong.", "Production designer Jack Fisk shaped the world to fit. The family home was in Smithville, Texas, and his team cut holes in the ceiling and added windows so daylight could reach the right places. He also planted gardens and trees so the setting could change with the seasons.", "The cosmic sequences went the other way: color invented on purpose. Douglas Trumbull, back in Hollywood after about 30 years, helped build them with practical methods, filming chemicals, paint, fluorescent dyes, smoke and liquids at high speed. The result is a film with two palettes, one quiet and found, one vivid and made by hand."], "images": [{"src": "img/films/the-tree-of-life-r1.jpg", "w": 900, "h": 600, "alt": "A wide, quiet main street in a small Texas town, lined with low brick storefronts under a pale sky.", "caption": "Downtown Smithville, Texas, the town where the film's family home was shot. A real photo (2012), not a still.", "credit": "Larry D. Moore · CC BY 4.0", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Main_street_smithville.jpg"}], "colors": [{"name": "Sky blue", "h": "#87CEEB", "app": "Sky blue", "note": "Daylight bounced into rooms through windows"}, {"name": "Golden hour", "h": "#F2B33D", "app": "Marigold", "note": "Sunlight from behind that rims faces and grass"}, {"name": "Lawn green", "h": "#7A9A5B", "app": "Moss", "note": "Gardens Jack Fisk planted to change with the seasons"}], "facts": [{"label": "Cinematography", "value": "Emmanuel Lubezki"}, {"label": "Production design", "value": "Jack Fisk"}, {"label": "Cosmic effects", "value": "Douglas Trumbull, with VFX supervisor Dan Glass"}, {"label": "Award", "value": "Palme d'Or, Cannes 2011"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Tree_of_Life_(film)"}, {"label": "Criterion", "url": "https://www.criterion.com/films/28576-the-tree-of-life"}], "sources": ["https://en.wikipedia.org/wiki/The_Tree_of_Life_(film)", "https://craigrichardscine.com/the-tree-of-life-the-dogma", "https://cinephiliabeyond.org/the-tree-of-life/", "https://www.icgmagazine.com/web/sights-unseen/"]},
{"id": "the-grand-budapest-hotel", "title": "The Grand Budapest Hotel", "year": 2014, "director": "Wes Anderson", "country": "United States, Germany", "dek": "Three eras, three frame shapes, and a pastel-pink hotel that fades to orange and beige.", "body": ["The Grand Budapest Hotel tells a story inside a story inside a story, and Wes Anderson gives each layer its own frame shape. The 1930s scenes use the nearly square 1.37:1 ratio of films from that era. The 1960s scenes stretch to wide 2.40:1, and the 1980s and present-day framing scenes use 1.85:1. Color changes with the frame.", "In the 1932 story the hotel is at its height, and the palette is rich: [[Pink|pinks]], reds and purples. On screen, the hotel's mountainside exterior is a pink confection, much of it a miniature about three meters tall. Milena Canonero dressed the concierge and his lobby boy in [[Purple|purple]] uniforms. One common reading is that the regal color lends the staff, and the hotel, a grand and formal air. The pastry boxes from Mendl's bakery, designed by the film's lead graphic designer, Annie Atkins, are a soft pink tied with ribbon, and they turn up again and again as a running motif.", "By 1968 the hotel has declined, and the palette has too. The colors turn to subdued beiges, [[Orange|orange]] and pale blue. The same rooms feel cheaper and sadder, though the building has not moved. The contrast teaches a simple idea: a place can age on screen through color alone.", "Much of the hotel interior was built inside a disused department store in Görlitz, Germany. Production designer Adam Stockhausen and Canonero both won Oscars for their work."], "images": [{"src": "img/films/the-grand-budapest-hotel-r1.jpg", "w": 553, "h": 900, "alt": "The tall atrium of an old department store, with ornate balconies, chandeliers and a stained-glass ceiling.", "caption": "Inside the disused department store in Görlitz, Germany, where much of the hotel interior was built. A photo of the real building (2015), not a still.", "credit": "Ubahnverleih · CC0", "license": "CC0", "licenseUrl": "https://creativecommons.org/publicdomain/zero/1.0/deed.en", "commons": "https://commons.wikimedia.org/wiki/File:Altes_Warenhaus_G%C3%B6rlitz,_Panorama_innen.jpg"}, {"src": "img/films/the-grand-budapest-hotel-r2.jpg", "w": 900, "h": 600, "alt": "The tall stone Art Nouveau facade of the Görlitz department store, behind a row of trees.", "caption": "The Görlitz department store from outside, a 1913 Art Nouveau building. A real photo (2010), not a still.", "credit": "Frank Vincentz · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:G%C3%B6rlitz_-_Marienplatz_-_Kaufhaus_01_ies.jpg"}], "colors": [{"name": "Hotel pink", "h": "#E8A0A8", "app": "Pink", "note": "The hotel's pastel front in its 1930s prime"}, {"name": "Mendl's pink", "h": "#F2C4CC", "app": "Baby pink", "note": "The pastry boxes that recur throughout the caper"}, {"name": "Royal purple", "h": "#5B2A86", "app": "Purple", "note": "The concierge and lobby boy uniforms"}, {"name": "Faded orange", "h": "#D9822B", "app": "Orange", "note": "The 1968 hotel, run down and redecorated"}, {"name": "Pale blue", "h": "#A9C6D6", "app": "Powder blue", "note": "Part of the subdued 1960s palette"}], "facts": [{"label": "Cinematography", "value": "Robert Yeoman"}, {"label": "Production design", "value": "Adam Stockhausen (Oscar winner)"}, {"label": "Costume design", "value": "Milena Canonero (Oscar winner)"}, {"label": "Aspect ratios", "value": "1.37:1 (1930s), 2.40:1 (1960s), 1.85:1 (later frames)"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/The_Grand_Budapest_Hotel"}, {"label": "Criterion", "url": "https://www.criterion.com/films/29601-the-grand-budapest-hotel"}], "sources": ["https://en.wikipedia.org/wiki/The_Grand_Budapest_Hotel", "https://www.criterion.com/films/29601-the-grand-budapest-hotel", "https://en.wikipedia.org/wiki/Annie_Atkins", "https://www.creativereview.co.uk/my-breakthrough-moment-annie-atkins/"]},
{"id": "mad-max-fury-road", "title": "Mad Max: Fury Road", "year": 2015, "director": "George Miller", "country": "Australia, United States", "dek": "A wasteland pushed to full color, then released again in black and white.", "body": ["Most films about the end of the world look washed out: grey, brown, drained. George Miller wanted the opposite. Colorist Eric Whipp has said Miller told him they would go either full black and white or full color, because he did not want yet another desaturated post-apocalyptic film. So they went to full color.", "The Namibian desert was graded hot and saturated, with sand pushed toward [[Orange|orange]] and the sky toward a deep [[Teal|teal]] blue. Orange and teal is a common Hollywood pairing, because warm skin and sand stand out against a cool background. Fury Road takes it about as far as it goes, so the chase reads clearly even when the cutting is very fast.", "Night is handled with a trick. Some night scenes were shot in daylight, two to three stops overexposed, then darkened in the grade into what Whipp called a spaghetti western blue. The result looks plainly stylized rather than real, and it keeps the action easy to follow.", "The other half of Miller's choice came later. In 2016 he released the Black & Chrome edition, a [[Black|black]]-and-white version graded with Whipp. Miller has said the best version of this movie is black and white, and that it felt more elemental. Watching both teaches a lot: the same shots read as a bright pop chase in color and as a starker, harder story without it."], "images": [{"src": "img/films/mad-max-fury-road-r1.jpg", "w": 900, "h": 675, "alt": "Rippled orange dunes under a clear blue sky in Namibia, with low mountains on the horizon.", "caption": "Dunes in Dorob National Park, Namibia, the region where most of the film was shot. Orange sand under a blue sky, the pair the grade pushed to the limit. A real photo (2009), not a still.", "credit": "Ebe 1003 · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Dorob_Nationalpark.jpg"}], "colors": [{"name": "Desert orange", "h": "#E9782B", "app": "Orange", "note": "Sand and dust pushed hot and saturated"}, {"name": "Sky teal", "h": "#1F7A8C", "app": "Teal", "note": "The cool sky that makes the warm desert pop"}, {"name": "Night blue", "h": "#1C3B6E", "app": "Navy", "note": "Day-for-night scenes darkened into a stylized blue"}, {"name": "Black", "h": "#16171A", "app": "Black", "note": "The Black & Chrome edition, released in 2016"}], "facts": [{"label": "Cinematography", "value": "John Seale"}, {"label": "Colorist", "value": "Eric Whipp"}, {"label": "Filmed in", "value": "Namibia, mainly around Dorob National Park"}, {"label": "Oscars", "value": "Six wins, including Production Design and Costume Design"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Mad_Max:_Fury_Road"}, {"label": "Warner Bros.", "url": "https://www.warnerbros.com/movies/mad-max-fury-road"}], "sources": ["https://en.wikipedia.org/wiki/Mad_Max:_Fury_Road", "https://www.filmmakeru.com/blog/colorist_eric_whipp", "https://www.inverse.com/article/21138-mad-max-fury-road-black-and-white-and-chrome-george-miller", "https://www.ericwhipp.com/madmax"]},
{"id": "moonlight", "title": "Moonlight", "year": 2016, "director": "Barry Jenkins", "country": "United States", "dek": "Three chapters of one life in Miami, each graded to look like a different film stock.", "body": ["Moonlight follows Chiron at three ages, growing up in Miami's Liberty Square housing project, where both Barry Jenkins and writer Tarell Alvin McCraney grew up. The title comes from McCraney's unpublished play In Moonlight Black Boys Look Blue. In the film, Juan, a father figure to young Chiron, remembers being nicknamed Blue as a boy, and says he later chose his own name. Blue becomes a thread through the film, often linked to the moments when Chiron is most exposed.", "A note on the title's idea: moonlight is not actually blue. It is sunlight reflected off the Moon, and a camera records it as fairly warm. It looks bluish to us because in dim light our eyes shift to rod vision, which favors blue-green. Films have long tinted night scenes [[Blue|blue]] to match that feeling, and Moonlight uses the convention as a poetic idea, not a fact.", "Jenkins and cinematographer James Laxton chose not to make a gritty, documentary-style film. They picked a digital camera partly for how well it rendered skin, and with colorist Alex Bickel they raised contrast and saturation while keeping detail in dark skin. Each chapter imitates a different film stock: Fuji in the first, to deepen skin tones; Agfa in the second, which adds [[Teal|cyan]]; and a modified Kodak look in the third.", "Critics have described the result as a Miami of piercing pinks and blues around warm, glowing faces. Jenkins has pointed out that film stock was long calibrated for white skin. For a designer, the lesson is that a grade is a point of view, and this one was built around the skin of the people on screen."], "images": [{"src": "img/films/moonlight-r1.jpg", "w": 900, "h": 675, "alt": "Low two-story pastel buildings around a lawn at the Liberty Square housing project in Miami.", "caption": "The Liberty Square housing project in Miami, where Chiron grows up in the film, and where Barry Jenkins and Tarell Alvin McCraney grew up. A real photo, not a still.", "credit": "305mia · CC BY 3.0", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Liberty_Square_Housing_Projects.jpg"}, {"src": "img/films/moonlight-r2.jpg", "w": 900, "h": 600, "alt": "The full Moon low over the blue band of Earth's atmosphere, photographed from orbit.", "caption": "The full Moon seen through Earth's atmosphere from the Space Shuttle in 1999. Moonlight is reflected sunlight; it looks bluish only because our eyes shift in dim light. A NASA photo, not from the film.", "credit": "NASA · Public domain", "license": "Public domain", "licenseUrl": "https://creativecommons.org/publicdomain/mark/1.0/", "commons": "https://commons.wikimedia.org/wiki/File:Full_moon_partially_obscured_by_atmosphere.jpg"}], "colors": [{"name": "Moonlight blue", "h": "#3A5BA0", "app": "Denim", "note": "The film's motif, tied to the play's title and Juan's nickname"}, {"name": "Agfa cyan", "h": "#2A9DA8", "app": "Teal", "note": "The cooler cast of the second chapter"}, {"name": "Miami pink", "h": "#F28DB2", "app": "Pink", "note": "Saturated city color around Chiron"}, {"name": "Warm skin glow", "h": "#8D5524", "app": "Sienna", "note": "The grade was built to make skin rich, not flat"}], "facts": [{"label": "Cinematography", "value": "James Laxton"}, {"label": "Colorist", "value": "Alex Bickel"}, {"label": "Based on", "value": "In Moonlight Black Boys Look Blue, by Tarell Alvin McCraney"}, {"label": "Oscars", "value": "Best Picture, Supporting Actor, Adapted Screenplay"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Moonlight_(2016_film)"}, {"label": "A24", "url": "https://a24films.com/films/moonlight"}], "sources": ["https://en.wikipedia.org/wiki/Moonlight_(2016_film)", "https://en.wikipedia.org/wiki/Purkinje_effect", "https://www.premiumbeat.com/blog/why-color-grade-moonlight-blue/", "https://a24films.com/films/moonlight"]},
{"id": "blade-runner-2049", "title": "Blade Runner 2049", "year": 2017, "director": "Denis Villeneuve", "country": "United States", "dek": "Each place gets its own light: grey rain, rippling gold, and a city drowned in orange dust.", "body": ["Blade Runner 2049 travels through very different worlds, and cinematographer Roger Deakins gives each one its own color of light. Almost all of it was made on set with filters and gels rather than added later in the grade. Deakins has said that basically everything was done in camera.", "Los Angeles is cold, wet and grey, with towering, Brutalist buildings drawn partly from the smog of Beijing. Against that [[Slate|slate]] haze, giant holograms and signs supply the only strong color.", "The ruined Las Vegas is the opposite: almost one color. Deakins took cues from photos of the 2009 red dust storm over Sydney. He had special camera filters made to push yellow and red, and gelled some lights green so that, through the filter, they came out yellow. The result is a city soaked in [[Burnt orange|burnt orange]], where depth comes from haze, not from contrast between hues.", "Inside the headquarters of the blind industrialist Wallace, the light moves. The office is a platform surrounded by water in a concrete box. The crew bounced big lamps off the water and used wave machines to stir it, so rippling caustic patterns crawl over the walls in warm [[Marigold|gold]]. Deakins has described the idea as artificial sunlight, always moving, for a man who cannot see it. For a designer, the film is a lesson in giving each space a single, strong lighting idea."], "images": [{"src": "img/films/blade-runner-2049-r1.jpg", "w": 900, "h": 603, "alt": "The Sydney Harbour Bridge fading into a thick orange-red haze over the water.", "caption": "The Sydney Harbour Bridge in the red dust storm of September 2009, the event Roger Deakins drew on for the film's Las Vegas. A real photo, not a still.", "credit": "John Byrne · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:SHB-Red-Dust.jpg"}, {"src": "img/films/blade-runner-2049-r2.jpg", "w": 900, "h": 800, "alt": "A pagoda on a distant hill, almost lost in grey haze, framed by dark trees.", "caption": "A pagoda near Beijing's Summer Palace, dimmed by smog (2014). Beijing's smog was one source for the film's grey Los Angeles. A real photo, not a still.", "credit": "Daniel Case · CC BY-SA 3.0", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0", "commons": "https://commons.wikimedia.org/wiki/File:Jade_Peak_Pagoda_in_smog_from_Longevity_Hill,_Beijing.jpg"}], "colors": [{"name": "Smog slate", "h": "#5F6B73", "app": "Slate", "note": "Rain-soaked Los Angeles, grey and heavy"}, {"name": "Dust-storm orange", "h": "#D0631C", "app": "Burnt orange", "note": "Las Vegas, inspired by the 2009 Sydney dust storm"}, {"name": "Caustic gold", "h": "#E8A33C", "app": "Marigold", "note": "Rippling water light in Wallace's headquarters"}], "facts": [{"label": "Cinematography", "value": "Roger Deakins (Oscar winner)"}, {"label": "Production design", "value": "Dennis Gassner"}, {"label": "Filmed in", "value": "Budapest, Hungary"}, {"label": "Method", "value": "Color built mostly on set with filters and gels"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Blade_Runner_2049"}, {"label": "Warner Bros.", "url": "https://www.warnerbros.com/movies/blade-runner-2049"}], "sources": ["https://en.wikipedia.org/wiki/Blade_Runner_2049", "https://filmmakermagazine.com/103272-the-color-of-the-future/", "https://www.studiobinder.com/blog/water-light-reflection-effect/", "https://theasc.com/article/uncanny-valley-blade-runner-2049/"]},
{"id": "barbie", "title": "Barbie", "year": 2023, "director": "Greta Gerwig", "country": "United States", "dek": "Barbie Land is built on painted skies and a lot of pink, and lit so the pink never takes over.", "body": ["Greta Gerwig wanted Barbie Land to feel like a toy world built on a soundstage. She took the idea from classic Technicolor musicals, with their painted skies and obvious sets, and called it authentic artificiality: the illusion is fake, but it is really there in front of the camera. So Barbie Land was a full set built at Warner Bros. Studios outside London, drawing on Palm Springs modernism, ringed by a huge hand-painted backdrop of [[Sky blue|blue sky]] and desert mountains instead of a green screen.", "Cinematographer Rodrigo Prieto split the film into two looks. Barbie Land uses a color setting based on three-strip Technicolor, which Gerwig nicknamed TechniBarbie. The real world uses a normal look based on film negative. Every day in Barbie Land is sunny, and the actors are mostly lit from behind.", "All that pink caused a practical problem: light bouncing off pink walls turns skin magenta. Prieto's fix was to use [[Grey|neutral grey]] material to bounce light into faces instead of the usual black. It is a useful lesson for anyone working with a strong color: it spreads onto everything near it.", "The pink also made news. Production designer Sarah Greenwood said the world ran out of pink, and the paint company Rosco confirmed a shortage of its fluorescent pink. Rosco also said supply chain trouble and a 2021 Texas freeze that hurt its materials were part of the cause, so the film did not cause the shortage alone. Greenwood later called her remark off the cuff and said there was not enough of that pink to begin with. Mattel's own Barbie pink is usually given as Pantone 219 C."], "images": [{"src": "img/films/barbie-r1.jpg", "w": 900, "h": 600, "alt": "A white mid-century modern house with a low roof, a bright yellow door and palm trees in Palm Springs.", "caption": "A mid-century modern house in Palm Springs, the style of architecture Barbie Land drew on. A real photo (2015), not a still.", "credit": "Wgreaves · CC BY-SA 4.0", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0", "commons": "https://commons.wikimedia.org/wiki/File:Mid-century_modern_house_in_Palm_Springs.jpg"}], "colors": [{"name": "Barbie pink", "h": "#DA1884", "app": "Mulberry", "note": "Mattel's brand pink, usually given as Pantone 219 C"}, {"name": "Fluorescent pink", "h": "#FF3EA5", "app": "Hot pink", "note": "The Rosco paint used across the Barbie Land sets"}, {"name": "Painted-sky blue", "h": "#8FC9EC", "app": "Sky blue", "note": "Hand-painted backdrops, real but obviously artificial"}, {"name": "Grey", "h": "#8C9096", "app": "Grey", "note": "Neutral fill that kept pink bounce off the actors' skin"}], "facts": [{"label": "Cinematography", "value": "Rodrigo Prieto"}, {"label": "Production design", "value": "Sarah Greenwood, with set decorator Katie Spencer"}, {"label": "Look", "value": "TechniBarbie, based on three-strip Technicolor"}, {"label": "Paint", "value": "Rosco fluorescent pink"}], "links": [{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Barbie_(film)"}, {"label": "Warner Bros.", "url": "https://www.warnerbros.com/movies/barbie"}], "sources": ["https://www.smithsonianmag.com/smart-news/barbie-movie-pink-paint-shortage-180982321/", "https://www.thewrap.com/barbie-cinematography-rodrigo-prieto-interview/", "https://www.thewrap.com/barbie-classic-movie-musicals-inspiration/", "https://www.dezeen.com/2023/07/20/sarah-greenwood-katie-spencer-absurd-set-barbie/", "https://www.cinemablend.com/movies/barbie-production-designer-walks-back-claims-international-pink-paint-shortage"]}
];
